 1→import { ChevronsUpDown, Plus, Settings } from "lucide-react";
 2→import { Link } from "@/lib/router";
 3→import { useCompany } from "../context/CompanyContext";
 4→import {
 5→  DropdownMenu,
 6→  DropdownMenuContent,
 7→  DropdownMenuItem,
 8→  DropdownMenuLabel,
 9→  DropdownMenuSeparator,
10→  DropdownMenuTrigger,
11→} from "@/components/ui/dropdown-menu";
12→import { Button } from "@/components/ui/button";
13→
14→function statusDotColor(status?: string): string {
15→  switch (status) {
16→    case "active":
17→      return "bg-green-400";
18→    case "paused":
19→      return "bg-yellow-400";
20→    case "archived":
21→      return "bg-neutral-400";
22→    default:
23→      return "bg-green-400";
24→  }
25→}
26→
27→export function CompanySwitcher() {
28→  const { companies, selectedCompany, setSelectedCompanyId } = useCompany();
29→  const sidebarCompanies = companies.filter((company) => company.status !== "archived");
30→
31→  return (
32→    <DropdownMenu>
33→      <DropdownMenuTrigger asChild>
34→        <Button
35→          variant="ghost"
36→          className="w-full justify-between px-2 py-1.5 h-auto text-left"
37→        >
38→          <div className="flex items-center gap-2 min-w-0">
39→            {selectedCompany && (
40→              <span className={`h-2 w-2 rounded-full shrink-0 ${statusDotColor(selectedCompany.status)}`} />
41→            )}
42→            <span className="text-sm font-medium truncate">
43→              {selectedCompany?.name ?? "Select company"}
44→            </span>
45→          </div>
46→          <ChevronsUpDown className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
47→        </Button>
48→      </DropdownMenuTrigger>
49→      <DropdownMenuContent align="start" className="w-[220px]">
50→        <DropdownMenuLabel>Companies</DropdownMenuLabel>
51→        <DropdownMenuSeparator />
52→        {sidebarCompanies.map((company) => (
53→          <DropdownMenuItem
54→            key={company.id}
55→            onClick={() => setSelectedCompanyId(company.id)}
56→            className={company.id === selectedCompany?.id ? "bg-accent" : ""}
57→          >
58→            <span className={`h-2 w-2 rounded-full shrink-0 mr-2 ${statusDotColor(company.status)}`} />
59→            <span className="truncate">{company.name}</span>
60→          </DropdownMenuItem>
61→        ))}
62→        {sidebarCompanies.length === 0 && (
63→          <DropdownMenuItem disabled>No companies</DropdownMenuItem>
64→        )}
65→        <DropdownMenuSeparator />
66→        <DropdownMenuItem asChild>
67→          <Link to="/company/settings" className="no-underline text-inherit">
68→            <Settings className="h-4 w-4 mr-2" />
69→            Company Settings
70→          </Link>
71→        </DropdownMenuItem>
72→        <DropdownMenuItem asChild>
73→          <Link to="/companies" className="no-underline text-inherit">
74→            <Plus className="h-4 w-4 mr-2" />
75→            Manage Companies
76→          </Link>
77→        </DropdownMenuItem>
78→      </DropdownMenuContent>
79→    </DropdownMenu>
80→  );
81→}
