  1→import { ChangeEvent, useEffect, useState } from "react";
  2→import { useMutation, useQueryClient } from "@tanstack/react-query";
  3→import { useCompany } from "../context/CompanyContext";
  4→import { useBreadcrumbs } from "../context/BreadcrumbContext";
  5→import { useToast } from "../context/ToastContext";
  6→import { companiesApi } from "../api/companies";
  7→import { accessApi } from "../api/access";
  8→import { assetsApi } from "../api/assets";
  9→import { queryKeys } from "../lib/queryKeys";
 10→import { Button } from "@/components/ui/button";
 11→import { Settings, Check, Download, Upload } from "lucide-react";
 12→import { CompanyPatternIcon } from "../components/CompanyPatternIcon";
 13→import {
 14→  Field,
 15→  ToggleField,
 16→  HintIcon
 17→} from "../components/agent-config-primitives";
 18→
 19→type AgentSnippetInput = {
 20→  onboardingTextUrl: string;
 21→  connectionCandidates?: string[] | null;
 22→  testResolutionUrl?: string | null;
 23→};
 24→
 25→export function CompanySettings() {
 26→  const {
 27→    companies,
 28→    selectedCompany,
 29→    selectedCompanyId,
 30→    setSelectedCompanyId
 31→  } = useCompany();
 32→  const { setBreadcrumbs } = useBreadcrumbs();
 33→  const { pushToast } = useToast();
 34→  const queryClient = useQueryClient();
 35→  // General settings local state
 36→  const [companyName, setCompanyName] = useState("");
 37→  const [description, setDescription] = useState("");
 38→  const [brandColor, setBrandColor] = useState("");
 39→  const [logoUrl, setLogoUrl] = useState("");
 40→  const [logoUploadError, setLogoUploadError] = useState<string | null>(null);
 41→
 42→  // Sync local state from selected company
 43→  useEffect(() => {
 44→    if (!selectedCompany) return;
 45→    setCompanyName(selectedCompany.name);
 46→    setDescription(selectedCompany.description ?? "");
 47→    setBrandColor(selectedCompany.brandColor ?? "");
 48→    setLogoUrl(selectedCompany.logoUrl ?? "");
 49→  }, [selectedCompany]);
 50→
 51→  const [inviteError, setInviteError] = useState<string | null>(null);
 52→  const [inviteSnippet, setInviteSnippet] = useState<string | null>(null);
 53→  const [snippetCopied, setSnippetCopied] = useState(false);
 54→  const [snippetCopyDelightId, setSnippetCopyDelightId] = useState(0);
 55→
 56→  const generalDirty =
 57→    !!selectedCompany &&
 58→    (companyName !== selectedCompany.name ||
 59→      description !== (selectedCompany.description ?? "") ||
 60→      brandColor !== (selectedCompany.brandColor ?? ""));
 61→
 62→  const generalMutation = useMutation({
 63→    mutationFn: (data: {
 64→      name: string;
 65→      description: string | null;
 66→      brandColor: string | null;
 67→    }) => companiesApi.update(selectedCompanyId!, data),
 68→    onSuccess: () => {
 69→      queryClient.invalidateQueries({ queryKey: queryKeys.companies.all });
 70→    }
 71→  });
 72→
 73→  const settingsMutation = useMutation({
 74→    mutationFn: (requireApproval: boolean) =>
 75→      companiesApi.update(selectedCompanyId!, {
 76→        requireBoardApprovalForNewAgents: requireApproval
 77→      }),
 78→    onSuccess: () => {
 79→      queryClient.invalidateQueries({ queryKey: queryKeys.companies.all });
 80→    }
 81→  });
 82→
 83→  const inviteMutation = useMutation({
 84→    mutationFn: () =>
 85→      accessApi.createOpenClawInvitePrompt(selectedCompanyId!),
 86→    onSuccess: async (invite) => {
 87→      setInviteError(null);
 88→      const base = window.location.origin.replace(/\/+$/, "");
 89→      const onboardingTextLink =
 90→        invite.onboardingTextUrl ??
 91→        invite.onboardingTextPath ??
 92→        `/api/invites/${invite.token}/onboarding.txt`;
 93→      const absoluteUrl = onboardingTextLink.startsWith("http")
 94→        ? onboardingTextLink
 95→        : `${base}${onboardingTextLink}`;
 96→      setSnippetCopied(false);
 97→      setSnippetCopyDelightId(0);
 98→      let snippet: string;
 99→      try {
100→        const manifest = await accessApi.getInviteOnboarding(invite.token);
101→        snippet = buildAgentSnippet({
102→          onboardingTextUrl: absoluteUrl,
103→          connectionCandidates:
104→            manifest.onboarding.connectivity?.connectionCandidates ?? null,
105→          testResolutionUrl:
106→            manifest.onboarding.connectivity?.testResolutionEndpoint?.url ??
107→            null
108→        });
109→      } catch {
110→        snippet = buildAgentSnippet({
111→          onboardingTextUrl: absoluteUrl,
112→          connectionCandidates: null,
113→          testResolutionUrl: null
114→        });
115→      }
116→      setInviteSnippet(snippet);
117→      try {
118→        await navigator.clipboard.writeText(snippet);
119→        setSnippetCopied(true);
120→        setSnippetCopyDelightId((prev) => prev + 1);
121→        setTimeout(() => setSnippetCopied(false), 2000);
122→      } catch {
123→        /* clipboard may not be available */
124→      }
125→      queryClient.invalidateQueries({
126→        queryKey: queryKeys.sidebarBadges(selectedCompanyId!)
127→      });
128→    },
129→    onError: (err) => {
130→      setInviteError(
131→        err instanceof Error ? err.message : "Failed to create invite"
132→      );
133→    }
134→  });
135→
136→  const syncLogoState = (nextLogoUrl: string | null) => {
137→    setLogoUrl(nextLogoUrl ?? "");
138→    void queryClient.invalidateQueries({ queryKey: queryKeys.companies.all });
139→  };
140→
141→  const logoUploadMutation = useMutation({
142→    mutationFn: (file: File) =>
143→      assetsApi
144→        .uploadCompanyLogo(selectedCompanyId!, file)
145→        .then((asset) => companiesApi.update(selectedCompanyId!, { logoAssetId: asset.assetId })),
146→    onSuccess: (company) => {
147→      syncLogoState(company.logoUrl);
148→      setLogoUploadError(null);
149→    }
150→  });
151→
152→  const clearLogoMutation = useMutation({
153→    mutationFn: () => companiesApi.update(selectedCompanyId!, { logoAssetId: null }),
154→    onSuccess: (company) => {
155→      setLogoUploadError(null);
156→      syncLogoState(company.logoUrl);
157→    }
158→  });
159→
160→  function handleLogoFileChange(event: ChangeEvent<HTMLInputElement>) {
161→    const file = event.target.files?.[0] ?? null;
162→    event.currentTarget.value = "";
163→    if (!file) return;
164→    setLogoUploadError(null);
165→    logoUploadMutation.mutate(file);
166→  }
167→
168→  function handleClearLogo() {
169→    clearLogoMutation.mutate();
170→  }
171→
172→  useEffect(() => {
173→    setInviteError(null);
174→    setInviteSnippet(null);
175→    setSnippetCopied(false);
176→    setSnippetCopyDelightId(0);
177→  }, [selectedCompanyId]);
178→
179→  const archiveMutation = useMutation({
180→    mutationFn: ({
181→      companyId,
182→      nextCompanyId
183→    }: {
184→      companyId: string;
185→      nextCompanyId: string | null;
186→    }) => companiesApi.archive(companyId).then(() => ({ nextCompanyId })),
187→    onSuccess: async ({ nextCompanyId }) => {
188→      if (nextCompanyId) {
189→        setSelectedCompanyId(nextCompanyId);
190→      }
191→      await queryClient.invalidateQueries({
192→        queryKey: queryKeys.companies.all
193→      });
194→      await queryClient.invalidateQueries({
195→        queryKey: queryKeys.companies.stats
196→      });
197→    }
198→  });
199→
200→  useEffect(() => {
201→    setBreadcrumbs([
202→      { label: selectedCompany?.name ?? "Company", href: "/dashboard" },
203→      { label: "Settings" }
204→    ]);
205→  }, [setBreadcrumbs, selectedCompany?.name]);
206→
207→  if (!selectedCompany) {
208→    return (
209→      <div className="text-sm text-muted-foreground">
210→        No company selected. Select a company from the switcher above.
211→      </div>
212→    );
213→  }
214→
215→  function handleSaveGeneral() {
216→    generalMutation.mutate({
217→      name: companyName.trim(),
218→      description: description.trim() || null,
219→      brandColor: brandColor || null
220→    });
221→  }
222→
223→  return (
224→    <div className="max-w-2xl space-y-6">
225→      <div className="flex items-center gap-2">
226→        <Settings className="h-5 w-5 text-muted-foreground" />
227→        <h1 className="text-lg font-semibold">Company Settings</h1>
228→      </div>
229→
230→      {/* General */}
231→      <div className="space-y-4">
232→        <div className="text-xs font-medium text-muted-foreground uppercase tracking-wide">
233→          General
234→        </div>
235→        <div className="space-y-3 rounded-md border border-border px-4 py-4">
236→          <Field label="Company name" hint="The display name for your company.">
237→            <input
238→              className="w-full rounded-md border border-border bg-transparent px-2.5 py-1.5 text-sm outline-none"
239→              type="text"
240→              value={companyName}
241→              onChange={(e) => setCompanyName(e.target.value)}
242→            />
243→          </Field>
244→          <Field
245→            label="Description"
246→            hint="Optional description shown in the company profile."
247→          >
248→            <input
249→              className="w-full rounded-md border border-border bg-transparent px-2.5 py-1.5 text-sm outline-none"
250→              type="text"
251→              value={description}
252→              placeholder="Optional company description"
253→              onChange={(e) => setDescription(e.target.value)}
254→            />
255→          </Field>
256→        </div>
257→      </div>
258→
259→      {/* Appearance */}
260→      <div className="space-y-4">
261→        <div className="text-xs font-medium text-muted-foreground uppercase tracking-wide">
262→          Appearance
263→        </div>
264→        <div className="space-y-3 rounded-md border border-border px-4 py-4">
265→          <div className="flex items-start gap-4">
266→            <div className="shrink-0">
267→              <CompanyPatternIcon
268→                companyName={companyName || selectedCompany.name}
269→                logoUrl={logoUrl || null}
270→                brandColor={brandColor || null}
271→                className="rounded-[14px]"
272→              />
273→            </div>
274→            <div className="flex-1 space-y-3">
275→              <Field
276→                label="Logo"
277→                hint="Upload a PNG, JPEG, WEBP, GIF, or SVG logo image."
278→              >
279→                <div className="space-y-2">
280→                  <input
281→                    type="file"
282→                    accept="image/png,image/jpeg,image/webp,image/gif,image/svg+xml"
283→                    onChange={handleLogoFileChange}
284→                    className="w-full rounded-md border border-border bg-transparent px-2.5 py-1.5 text-sm outline-none file:mr-4 file:rounded-md file:border-0 file:bg-muted file:px-2.5 file:py-1 file:text-xs"
285→                  />
286→                  {logoUrl && (
287→                    <div className="flex items-center gap-2">
288→                      <Button
289→                        size="sm"
290→                        variant="outline"
291→                        onClick={handleClearLogo}
292→                        disabled={clearLogoMutation.isPending}
293→                      >
294→                        {clearLogoMutation.isPending ? "Removing..." : "Remove logo"}
295→                      </Button>
296→                    </div>
297→                  )}
298→                  {(logoUploadMutation.isError || logoUploadError) && (
299→                    <span className="text-xs text-destructive">
300→                      {logoUploadError ??
301→                        (logoUploadMutation.error instanceof Error
302→                          ? logoUploadMutation.error.message
303→                          : "Logo upload failed")}
304→                    </span>
305→                  )}
306→                  {clearLogoMutation.isError && (
307→                    <span className="text-xs text-destructive">
308→                      {clearLogoMutation.error.message}
309→                    </span>
310→                  )}
311→                  {logoUploadMutation.isPending && (
312→                    <span className="text-xs text-muted-foreground">Uploading logo...</span>
313→                  )}
314→                </div>
315→              </Field>
316→              <Field
317→                label="Brand color"
318→                hint="Sets the hue for the company icon. Leave empty for auto-generated color."
319→              >
320→                <div className="flex items-center gap-2">
321→                  <input
322→                    type="color"
323→                    value={brandColor || "#6366f1"}
324→                    onChange={(e) => setBrandColor(e.target.value)}
325→                    className="h-8 w-8 cursor-pointer rounded border border-border bg-transparent p-0"
326→                  />
327→                  <input
328→                    type="text"
329→                    value={brandColor}
330→                    onChange={(e) => {
331→                      const v = e.target.value;
332→                      if (v === "" || /^#[0-9a-fA-F]{0,6}$/.test(v)) {
333→                        setBrandColor(v);
334→                      }
335→                    }}
336→                    placeholder="Auto"
337→                    className="w-28 rounded-md border border-border bg-transparent px-2.5 py-1.5 text-sm font-mono outline-none"
338→                  />
339→                  {brandColor && (
340→                    <Button
341→                      size="sm"
342→                      variant="ghost"
343→                      onClick={() => setBrandColor("")}
344→                      className="text-xs text-muted-foreground"
345→                    >
346→                      Clear
347→                    </Button>
348→                  )}
349→                </div>
350→              </Field>
351→            </div>
352→          </div>
353→        </div>
354→      </div>
355→
356→      {/* Save button for General + Appearance */}
357→      {generalDirty && (
358→        <div className="flex items-center gap-2">
359→          <Button
360→            size="sm"
361→            onClick={handleSaveGeneral}
362→            disabled={generalMutation.isPending || !companyName.trim()}
363→          >
364→            {generalMutation.isPending ? "Saving..." : "Save changes"}
365→          </Button>
366→          {generalMutation.isSuccess && (
367→            <span className="text-xs text-muted-foreground">Saved</span>
368→          )}
369→          {generalMutation.isError && (
370→            <span className="text-xs text-destructive">
371→              {generalMutation.error instanceof Error
372→                  ? generalMutation.error.message
373→                  : "Failed to save"}
374→            </span>
375→          )}
376→        </div>
377→      )}
378→
379→      {/* Hiring */}
380→      <div className="space-y-4">
381→        <div className="text-xs font-medium text-muted-foreground uppercase tracking-wide">
382→          Hiring
383→        </div>
384→        <div className="rounded-md border border-border px-4 py-3">
385→          <ToggleField
386→            label="Require board approval for new hires"
387→            hint="New agent hires stay pending until approved by board."
388→            checked={!!selectedCompany.requireBoardApprovalForNewAgents}
389→            onChange={(v) => settingsMutation.mutate(v)}
390→          />
391→        </div>
392→      </div>
393→
394→      {/* Invites */}
395→      <div className="space-y-4">
396→        <div className="text-xs font-medium text-muted-foreground uppercase tracking-wide">
397→          Invites
398→        </div>
399→        <div className="space-y-3 rounded-md border border-border px-4 py-4">
400→          <div className="flex items-center gap-1.5">
401→            <span className="text-xs text-muted-foreground">
402→              Generate an OpenClaw agent invite snippet.
403→            </span>
404→            <HintIcon text="Creates a short-lived OpenClaw agent invite and renders a copy-ready prompt." />
405→          </div>
406→          <div className="flex flex-wrap items-center gap-2">
407→            <Button
408→              size="sm"
409→              onClick={() => inviteMutation.mutate()}
410→              disabled={inviteMutation.isPending}
411→            >
412→              {inviteMutation.isPending
413→                ? "Generating..."
414→                : "Generate OpenClaw Invite Prompt"}
415→            </Button>
416→          </div>
417→          {inviteError && (
