 34→const ORDER_STORAGE_KEY = "paperclip.companyOrder";
 35→
 36→function getStoredOrder(): string[] {
 37→  try {
 38→    const raw = localStorage.getItem(ORDER_STORAGE_KEY);
 39→    if (raw) return JSON.parse(raw);
 40→  } catch { /* ignore */ }
 41→  return [];
 42→}
 43→
 44→function saveOrder(ids: string[]) {
 45→  localStorage.setItem(ORDER_STORAGE_KEY, JSON.stringify(ids));
 46→}
 47→
 48→/** Sort companies by stored order, appending any new ones at the end. */
 49→function sortByStoredOrder(companies: Company[]): Company[] {
 50→  const order = getStoredOrder();
 51→  if (order.length === 0) return companies;
 52→
 53→  const byId = new Map(companies.map((c) => [c.id, c]));
 54→  const sorted: Company[] = [];
 55→
 56→  for (const id of order) {
 57→    const c = byId.get(id);
 58→    if (c) {
 59→      sorted.push(c);
 60→      byId.delete(id);
 61→    }
 62→  }
 63→  // Append any companies not in stored order
 64→  for (const c of byId.values()) {
 65→    sorted.push(c);
 66→  }
 67→  return sorted;
 68→}
