156→export function CompanyRail() {
157→  const { companies, selectedCompanyId, setSelectedCompanyId } = useCompany();
158→  const { openOnboarding } = useDialog();
159→  const navigate = useNavigate();
160→  const location = useLocation();
161→  const isInstanceRoute = location.pathname.startsWith("/instance/");
162→  const highlightedCompanyId = isInstanceRoute ? null : selectedCompanyId;
163→  const sidebarCompanies = useMemo(
164→    () => companies.filter((company) => company.status !== "archived"),
165→    [companies],
166→  );
167→  const companyIds = useMemo(() => sidebarCompanies.map((company) => company.id), [sidebarCompanies]);
168→
169→  const liveRunsQueries = useQueries({
170→    queries: companyIds.map((companyId) => ({
171→      queryKey: queryKeys.liveRuns(companyId),
172→      queryFn: () => heartbeatsApi.liveRunsForCompany(companyId),
173→      refetchInterval: 10_000,
174→    })),
175→  });
176→  const sidebarBadgeQueries = useQueries({
177→    queries: companyIds.map((companyId) => ({
178→      queryKey: queryKeys.sidebarBadges(companyId),
179→      queryFn: () => sidebarBadgesApi.get(companyId),
180→      refetchInterval: 15_000,
181→    })),
182→  });
183→  const hasLiveAgentsByCompanyId = useMemo(() => {
184→    const result = new Map<string, boolean>();
185→    companyIds.forEach((companyId, index) => {
186→      result.set(companyId, (liveRunsQueries[index]?.data?.length ?? 0) > 0);
187→    });
188→    return result;
189→  }, [companyIds, liveRunsQueries]);
190→  const hasUnreadInboxByCompanyId = useMemo(() => {
191→    const result = new Map<string, boolean>();
192→    companyIds.forEach((companyId, index) => {
193→      result.set(companyId, (sidebarBadgeQueries[index]?.data?.inbox ?? 0) > 0);
194→    });
195→    return result;
196→  }, [companyIds, sidebarBadgeQueries]);
197→
198→  // Maintain sorted order in local state, synced from companies + localStorage
199→  const [orderedIds, setOrderedIds] = useState<string[]>(() =>
200→    sortByStoredOrder(sidebarCompanies).map((c) => c.id)
201→  );
202→
203→  // Re-sync orderedIds from localStorage whenever companies changes.
204→  // Handles initial data load (companies starts as [] before query resolves)
205→  // and subsequent refetches triggered by live updates.
206→  useEffect(() => {
207→    if (sidebarCompanies.length === 0) {
208→      setOrderedIds([]);
209→      return;
210→    }
211→    setOrderedIds(sortByStoredOrder(sidebarCompanies).map((c) => c.id));
212→  }, [sidebarCompanies]);
213→
214→  // Sync order across tabs via the native storage event
215→  useEffect(() => {
216→    const handleStorage = (e: StorageEvent) => {
217→      if (e.key !== ORDER_STORAGE_KEY) return;
218→      try {
219→        const ids: string[] = e.newValue ? JSON.parse(e.newValue) : [];
220→        setOrderedIds(ids);
221→      } catch { /* ignore malformed data */ }
222→    };
223→    window.addEventListener("storage", handleStorage);
224→    return () => window.removeEventListener("storage", handleStorage);
225→  }, []);
226→
227→  // Re-derive when companies change (new company added/removed)
228→  const orderedCompanies = useMemo(() => {
229→    const byId = new Map(sidebarCompanies.map((c) => [c.id, c]));
230→    const result: Company[] = [];
231→    for (const id of orderedIds) {
232→      const c = byId.get(id);
233→      if (c) {
234→        result.push(c);
235→        byId.delete(id);
236→      }
237→    }
238→    // Append any new companies not yet in our order
239→    for (const c of byId.values()) {
240→      result.push(c);
241→    }
242→    return result;
243→  }, [sidebarCompanies, orderedIds]);
244→
245→  // Require 8px of movement before starting a drag to avoid interfering with clicks
246→  const sensors = useSensors(
247→    useSensor(PointerSensor, {
248→      activationConstraint: { distance: 8 },
249→    })
250→  );
251→
252→  const handleDragEnd = useCallback(
253→    (event: DragEndEvent) => {
254→      const { active, over } = event;
255→      if (!over || active.id === over.id) return;
256→
257→      const ids = orderedCompanies.map((c) => c.id);
258→      const oldIndex = ids.indexOf(active.id as string);
259→      const newIndex = ids.indexOf(over.id as string);
260→      if (oldIndex === -1 || newIndex === -1) return;
261→
262→      const newIds = arrayMove(ids, oldIndex, newIndex);
263→      setOrderedIds(newIds);
264→      saveOrder(newIds);
265→    },
266→    [orderedCompanies]
267→  );
268→
269→  return (
270→    <div className="flex flex-col items-center w-[72px] shrink-0 h-full bg-background border-r border-border">
271→      {/* Paperclip icon - aligned with top sections (implied line, no visible border) */}
272→      <div className="flex items-center justify-center h-12 w-full shrink-0">
273→        <Paperclip className="h-5 w-5 text-foreground" />
274→      </div>
275→
276→      {/* Company list */}
277→      <div className="flex-1 flex flex-col items-center gap-2 py-3 w-full overflow-y-auto overflow-x-hidden scrollbar-none">
278→        <DndContext
279→          sensors={sensors}
280→          collisionDetection={closestCenter}
281→          onDragEnd={handleDragEnd}
282→        >
283→          <SortableContext
284→            items={orderedCompanies.map((c) => c.id)}
285→            strategy={verticalListSortingStrategy}
286→          >
287→            {orderedCompanies.map((company) => (
288→              <SortableCompanyItem
289→                key={company.id}
290→                company={company}
291→                isSelected={company.id === highlightedCompanyId}
292→                hasLiveAgents={hasLiveAgentsByCompanyId.get(company.id) ?? false}
293→                hasUnreadInbox={hasUnreadInboxByCompanyId.get(company.id) ?? false}
294→                onSelect={() => {
295→                  setSelectedCompanyId(company.id);
296→                  if (isInstanceRoute) {
297→                    navigate(`/${company.issuePrefix}/dashboard`);
298→                  }
299→                }}
300→              />
301→            ))}
302→          </SortableContext>
303→        </DndContext>
304→      </div>
305→
306→      {/* Separator before add button */}
307→      <div className="w-8 h-px bg-border mx-auto shrink-0" />
308→
309→      {/* Add company button */}
310→      <div className="flex items-center justify-center py-2 shrink-0">
311→        <Tooltip delayDuration={300}>
312→          <TooltipTrigger asChild>
313→            <button
314→              onClick={() => openOnboarding()}
315→              className="flex items-center justify-center w-11 h-11 rounded-[22px] hover:rounded-[14px] border-2 border-dashed border-border text-muted-foreground hover:border-foreground/30 hover:text-foreground transition-[border-color,color,border-radius] duration-150"
316→              aria-label="Add company"
317→            >
318→              <Plus className="h-5 w-5" />
319→            </button>
320→          </TooltipTrigger>
321→          <TooltipContent side="right" sideOffset={8}>
322→            <p>Add company</p>
323→          </TooltipContent>
324→        </Tooltip>
325→      </div>
326→    </div>
327→  );
328→}
