 18→function hashString(value: string): number {
 19→  let hash = 2166136261;
 20→  for (let i = 0; i < value.length; i++) {
 21→    hash ^= value.charCodeAt(i);
 22→    hash = Math.imul(hash, 16777619);
 23→  }
 24→  return hash >>> 0;
 25→}
 26→
 27→function mulberry32(seed: number): () => number {
 28→  let state = seed >>> 0;
 29→  return () => {
 30→    state = (state + 0x6d2b79f5) >>> 0;
 31→    let t = Math.imul(state ^ (state >>> 15), 1 | state);
 32→    t ^= t + Math.imul(t ^ (t >>> 7), 61 | t);
 33→    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
 34→  };
 35→}
 36→
 37→function hslToRgb(h: number, s: number, l: number): [number, number, number] {
 38→  const hue = ((h % 360) + 360) % 360;
 39→  const sat = Math.max(0, Math.min(100, s)) / 100;
 40→  const light = Math.max(0, Math.min(100, l)) / 100;
 41→
 42→  const c = (1 - Math.abs(2 * light - 1)) * sat;
 43→  const x = c * (1 - Math.abs(((hue / 60) % 2) - 1));
 44→  const m = light - c / 2;
 45→
 46→  let r = 0;
 47→  let g = 0;
 48→  let b = 0;
 49→
 50→  if (hue < 60) {
 51→    r = c;
 52→    g = x;
 53→  } else if (hue < 120) {
 54→    r = x;
 55→    g = c;
 56→  } else if (hue < 180) {
 57→    g = c;
 58→    b = x;
 59→  } else if (hue < 240) {
 60→    g = x;
 61→    b = c;
 62→  } else if (hue < 300) {
 63→    r = x;
 64→    b = c;
 65→  } else {
 66→    r = c;
 67→    b = x;
 68→  }
 69→
 70→  return [
 71→    Math.round((r + m) * 255),
 72→    Math.round((g + m) * 255),
 73→    Math.round((b + m) * 255),
 74→  ];
 75→}
 76→
 77→function hexToHue(hex: string): number {
 78→  const r = parseInt(hex.slice(1, 3), 16) / 255;
 79→  const g = parseInt(hex.slice(3, 5), 16) / 255;
 80→  const b = parseInt(hex.slice(5, 7), 16) / 255;
 81→  const max = Math.max(r, g, b);
 82→  const min = Math.min(r, g, b);
 83→  const d = max - min;
 84→  if (d === 0) return 0;
 85→  let h = 0;
 86→  if (max === r) h = ((g - b) / d) % 6;
 87→  else if (max === g) h = (b - r) / d + 2;
 88→  else h = (r - g) / d + 4;
 89→  return ((h * 60) + 360) % 360;
 90→}
