 92→function makeCompanyPatternDataUrl(seed: string, brandColor?: string | null, logicalSize = 22, cellSize = 2): string {
 93→  if (typeof document === "undefined") return "";
 94→
 95→  const canvas = document.createElement("canvas");
 96→  canvas.width = logicalSize * cellSize;
 97→  canvas.height = logicalSize * cellSize;
 98→
 99→  const ctx = canvas.getContext("2d");
100→  if (!ctx) return "";
101→
102→  const rand = mulberry32(hashString(seed));
103→
104→  const hue = brandColor ? hexToHue(brandColor) : Math.floor(rand() * 360);
105→  const [offR, offG, offB] = hslToRgb(
106→    hue,
107→    54 + Math.floor(rand() * 14),
108→    36 + Math.floor(rand() * 12),
109→  );
110→  const [onR, onG, onB] = hslToRgb(
111→    hue + (rand() > 0.5 ? 10 : -10),
112→    86 + Math.floor(rand() * 10),
113→    82 + Math.floor(rand() * 10),
114→  );
115→
116→  const center = (logicalSize - 1) / 2;
117→  const half = Math.max(center, 1);
118→  const gradientAngle = rand() * Math.PI * 2;
119→  const gradientDirX = Math.cos(gradientAngle);
120→  const gradientDirY = Math.sin(gradientAngle);
121→  const maxProjection = Math.abs(gradientDirX * half) + Math.abs(gradientDirY * half);
122→  const diagonalFrequency = 0.34 + rand() * 0.12;
123→  const antiDiagonalFrequency = 0.33 + rand() * 0.12;
124→  const diagonalPhase = rand() * Math.PI * 2;
125→  const antiDiagonalPhase = rand() * Math.PI * 2;
126→
127→  ctx.fillStyle = `rgb(${offR} ${offG} ${offB})`;
128→  ctx.fillRect(0, 0, canvas.width, canvas.height);
129→
130→  ctx.fillStyle = `rgb(${onR} ${onG} ${onB})`;
131→  const dotRadius = cellSize * 0.46;
132→
133→  for (let y = 0; y < logicalSize; y++) {
134→    const dy = y - center;
135→
136→    for (let x = 0; x < logicalSize; x++) {
137→      const dx = x - center;
138→
139→      // Side-to-side signal where visible gradient is produced by dither density.
140→      const projection = dx * gradientDirX + dy * gradientDirY;
141→      const gradient = (projection / maxProjection + 1) * 0.5;
142→      const diagonal = Math.sin((dx + dy) * diagonalFrequency + diagonalPhase) * 0.5 + 0.5;
143→      const antiDiagonal = Math.sin((dx - dy) * antiDiagonalFrequency + antiDiagonalPhase) * 0.5 + 0.5;
144→      const hatch = diagonal * 0.5 + antiDiagonal * 0.5;
145→      const signal = Math.max(0, Math.min(1, gradient + (hatch - 0.5) * 0.22));
146→
147→      // Canonical 16-level ordered dither: level 0..15 compared to Bayer 4x4 threshold index.
148→      const level = Math.max(0, Math.min(15, Math.floor(signal * 16)));
149→      const thresholdIndex = BAYER_4X4[y & 3]![x & 3]!;
150→      if (level <= thresholdIndex) continue;
151→
152→      const cx = x * cellSize + cellSize / 2;
153→      const cy = y * cellSize + cellSize / 2;
154→      ctx.beginPath();
155→      ctx.arc(cx, cy, dotRadius, 0, Math.PI * 2);
156→      ctx.fill();
157→    }
158→  }
159→
160→  return canvas.toDataURL("image/png");
161→}
