  37→/**
  38→ * Subset of JSON Schema properties we understand for form rendering.
  39→ * We intentionally keep this loose (`Record<string, unknown>`) at the top
  40→ * level to match the `JsonSchema` type in shared, but narrow internally.
  41→ */
  42→export interface JsonSchemaNode {
  43→  type?: string | string[];
  44→  title?: string;
  45→  description?: string;
  46→  default?: unknown;
  47→  enum?: unknown[];
  48→  const?: unknown;
  49→  format?: string;
  50→
  51→  // String constraints
  52→  minLength?: number;
  53→  maxLength?: number;
  54→  pattern?: string;
  55→
  56→  // Number constraints
  57→  minimum?: number;
  58→  maximum?: number;
  59→  exclusiveMinimum?: number;
  60→  exclusiveMaximum?: number;
  61→  multipleOf?: number;
  62→
  63→  // Object
  64→  properties?: Record<string, JsonSchemaNode>;
  65→  required?: string[];
  66→  additionalProperties?: boolean | JsonSchemaNode;
  67→
  68→  // Array
  69→  items?: JsonSchemaNode;
  70→  minItems?: number;
  71→  maxItems?: number;
  72→
  73→  // Metadata
  74→  readOnly?: boolean;
  75→  writeOnly?: boolean;
  76→
  77→  // Allow extra keys
  78→  [key: string]: unknown;
  79→}
  80→
  81→export interface JsonSchemaFormProps {
  82→  /** The JSON Schema to render. */
  83→  schema: JsonSchemaNode;
  84→  /** Current form values. */
  85→  values: Record<string, unknown>;
  86→  /** Called whenever any field value changes. */
  87→  onChange: (values: Record<string, unknown>) => void;
  88→  /** Validation errors keyed by JSON pointer path (e.g. "/apiKey"). */
  89→  errors?: Record<string, string>;
  90→  /** If true, all fields are disabled. */
  91→  disabled?: boolean;
  92→  /** Additional CSS class for the root container. */
  93→  className?: string;
