 153→/** Validate a single field value against schema constraints. Returns error string or null. */
 154→export function validateField(
 155→  value: unknown,
 156→  schema: JsonSchemaNode,
 157→  isRequired: boolean,
 158→): string | null {
 159→  const type = resolveType(schema);
 160→
 161→  // Required check
 162→  if (isRequired && (value === undefined || value === null || value === "")) {
 163→    return "This field is required";
 164→  }
 165→
 166→  // Skip further validation if empty and not required
 167→  if (value === undefined || value === null || value === "") return null;
 168→
 169→  if (type === "string" || type === "secret-ref") {
 170→    const str = String(value);
 171→    if (schema.minLength != null && str.length < schema.minLength) {
 172→      return `Must be at least ${schema.minLength} characters`;
 173→    }
 174→    if (schema.maxLength != null && str.length > schema.maxLength) {
 175→      return `Must be at most ${schema.maxLength} characters`;
 176→    }
 177→    if (schema.pattern) {
 178→      // Guard against ReDoS: reject overly complex patterns from plugin JSON Schemas.
 179→      // Limit pattern length and run the regex with a defensive try/catch.
 180→      const MAX_PATTERN_LENGTH = 512;
 181→      if (schema.pattern.length <= MAX_PATTERN_LENGTH) {
 182→        try {
 183→          const re = new RegExp(schema.pattern);
 184→          if (!re.test(str)) {
 185→            return `Must match pattern: ${schema.pattern}`;
 186→          }
 187→        } catch {
 188→          // Invalid regex in schema — skip
 189→        }
 190→      }
 191→    }
 192→  }
 193→
 194→  if (type === "number" || type === "integer") {
 195→    const num = Number(value);
 196→    if (isNaN(num)) return "Must be a valid number";
 197→    if (schema.minimum != null && num < schema.minimum) {
 198→      return `Must be at least ${schema.minimum}`;
 199→    }
 200→    if (schema.maximum != null && num > schema.maximum) {
 201→      return `Must be at most ${schema.maximum}`;
 202→    }
 203→    if (schema.exclusiveMinimum != null && num <= schema.exclusiveMinimum) {
 204→      return `Must be greater than ${schema.exclusiveMinimum}`;
 205→    }
 206→    if (schema.exclusiveMaximum != null && num >= schema.exclusiveMaximum) {
 207→      return `Must be less than ${schema.exclusiveMaximum}`;
 208→    }
 209→    if (type === "integer" && !Number.isInteger(num)) {
 210→      return "Must be a whole number";
 211→    }
 212→    if (schema.multipleOf != null && num % schema.multipleOf !== 0) {
 213→      return `Must be a multiple of ${schema.multipleOf}`;
 214→    }
 215→  }
 216→
 217→  if (type === "array") {
 218→    const arr = value as unknown[];
 219→    if (schema.minItems != null && arr.length < schema.minItems) {
 220→      return `Must have at least ${schema.minItems} items`;
 221→    }
 222→    if (schema.maxItems != null && arr.length > schema.maxItems) {
 223→      return `Must have at most ${schema.maxItems} items`;
 224→    }
 225→  }
 226→
 227→  return null;
 228→}
