 831→/**
 832→ * Orchestrator component that selects and renders the appropriate field type based on the schema node.
 833→ */
 834→const FormField = React.memo(({
 835→  propSchema,
 836→  value,
 837→  onChange,
 838→  error,
 839→  disabled,
 840→  label,
 841→  isRequired,
 842→  errors,
 843→  path,
 844→}: FormFieldProps) => {
 845→  const type = resolveType(propSchema);
 846→  const isReadOnly = disabled || propSchema.readOnly === true;
 847→
 848→  switch (type) {
 849→    case "boolean":
 850→      return (
 851→        <BooleanField
 852→          id={path}
 853→          value={value}
 854→          onChange={onChange}
 855→          disabled={isReadOnly}
 856→          label={label}
 857→          isRequired={isRequired}
 858→          description={propSchema.description}
 859→          error={error}
 860→        />
 861→      );
 862→
 863→    case "enum":
 864→      return (
 865→        <EnumField
 866→          value={value}
 867→          onChange={onChange}
 868→          disabled={isReadOnly}
 869→          label={label}
 870→          isRequired={isRequired}
 871→          description={propSchema.description}
 872→          error={error}
 873→          options={propSchema.enum ?? []}
 874→        />
 875→      );
 876→
 877→    case "secret-ref":
 878→      return (
 879→        <SecretField
 880→          value={value}
 881→          onChange={onChange}
 882→          disabled={isReadOnly}
 883→          label={label}
 884→          isRequired={isRequired}
 885→          description={propSchema.description}
 886→          error={error}
 887→          defaultValue={propSchema.default}
 888→        />
 889→      );
 890→
 891→    case "number":
 892→    case "integer":
 893→      return (
 894→        <NumberField
 895→          value={value}
 896→          onChange={onChange}
 897→          disabled={isReadOnly}
 898→          label={label}
 899→          isRequired={isRequired}
 900→          description={propSchema.description}
 901→          error={error}
 902→          defaultValue={propSchema.default}
 903→          type={type as "number" | "integer"}
 904→        />
 905→      );
 906→
 907→    case "array":
 908→      return (
 909→        <ArrayField
 910→          propSchema={propSchema}
 911→          value={value}
 912→          onChange={onChange}
 913→          error={error}
 914→          disabled={isReadOnly}
 915→          label={label}
 916→          errors={errors}
 917→          path={path}
 918→        />
 919→      );
 920→
 921→    case "object":
 922→      return (
 923→        <ObjectField
 924→          propSchema={propSchema}
 925→          value={value}
 926→          onChange={onChange}
 927→          disabled={isReadOnly}
 928→          label={label}
 929→          errors={errors}
 930→          path={path}
 931→        />
 932→      );
 933→
 934→    default: // string
 935→      return (
 936→        <StringField
 937→          value={value}
 938→          onChange={onChange}
 939→          disabled={isReadOnly}
 940→          label={label}
 941→          isRequired={isRequired}
 942→          description={propSchema.description}
 943→          error={error}
 944→          defaultValue={propSchema.default}
 945→          format={propSchema.format}
 946→          maxLength={propSchema.maxLength}
 947→        />
 948→      );
 949→  }
 950→});
 951→
 952→FormField.displayName = "FormField";
 953→
 954→// ---------------------------------------------------------------------------
 955→// Main Component
 956→// ---------------------------------------------------------------------------
 957→
 958→/**
 959→ * Main JsonSchemaForm component.
 960→ * Renders a form based on a subset of JSON Schema specification.
 961→ * Supports primitive types, enums, secrets, objects, and arrays with recursion.
 962→ */
 963→export function JsonSchemaForm({
 964→  schema,
 965→  values,
 966→  onChange,
 967→  errors = {},
 968→  disabled,
 969→  className,
 970→}: JsonSchemaFormProps) {
 971→  const type = resolveType(schema);
 972→
 973→  const handleRootScalarChange = useCallback((newVal: unknown) => {
 974→    // If root is a scalar, values IS the value
 975→    onChange(newVal as Record<string, unknown>);
 976→  }, [onChange]);
 977→
 978→  // If it's a scalar at root, render a single FormField
 979→  if (type !== "object") {
 980→    return (
 981→      <div className={className}>
 982→        <FormField
 983→          propSchema={schema}
 984→          value={values}
 985→          label=""
 986→          path=""
 987→          onChange={handleRootScalarChange}
 988→          disabled={disabled}
 989→          errors={errors}
 990→        />
 991→      </div>
 992→    );
 993→  }
 994→
 995→  // Memoize to avoid re-renders when parent provides new object references
 996→  const properties = useMemo(() => schema.properties ?? {}, [schema.properties]);
 997→  const requiredFields = useMemo(
 998→    () => new Set(schema.required ?? []),
 999→    [schema.required],
1000→  );
1001→
1002→  const handleFieldChange = useCallback(
1003→    (key: string, value: unknown) => {
1004→      onChange({ ...values, [key]: value });
1005→    },
1006→    [onChange, values],
1007→  );
1008→
1009→  if (Object.keys(properties).length === 0) {
1010→    return (
1011→      <div
1012→        className={cn(
1013→          "py-4 text-center text-sm text-muted-foreground",
1014→          className,
1015→        )}
1016→      >
1017→        No configuration options available.
1018→      </div>
1019→    );
1020→  }
1021→
1022→  return (
1023→    <div className={cn("space-y-6", className)}>
1024→      {Object.entries(properties).map(([key, propSchema]) => {
1025→        const value = values[key];
1026→        const isRequired = requiredFields.has(key);
1027→        const error = errors[`/${key}`];
1028→        const label = labelFromKey(key, propSchema);
1029→        const path = `/${key}`;
1030→
1031→        return (
1032→          <FormField
1033→            key={key}
1034→            propSchema={propSchema}
1035→            value={value}
1036→            onChange={(val) => handleFieldChange(key, val)}
1037→            error={error}
1038→            disabled={disabled}
1039→            label={label}
1040→            isRequired={isRequired}
1041→            errors={errors}
1042→            path={path}
1043→          />
1044→        );
1045→      })}
1046→    </div>
1047→  );
1048→}
