549→function buildAgentSnippet(input: AgentSnippetInput) {
550→  const candidateUrls = buildCandidateOnboardingUrls(input);
551→  const resolutionTestUrl = buildResolutionTestUrl(input);
552→
553→  const candidateList =
554→    candidateUrls.length > 0
555→      ? candidateUrls.map((u) => `- ${u}`).join("\n")
556→      : "- (No candidate URLs available yet.)";
557→
558→  const connectivityBlock =
559→    candidateUrls.length === 0
560→      ? `No candidate URLs are available. Ask your user to configure a reachable hostname in Paperclip, then retry.
561→Suggested steps:
562→- choose a hostname that resolves to the Paperclip host from your runtime
563→- run: pnpm paperclipai allowed-hostname <host>
564→- restart Paperclip
565→- verify with: curl -fsS http://<host>:3100/api/health
566→- regenerate this invite snippet`
567→      : `If none are reachable, ask your user to add a reachable hostname in Paperclip, restart, and retry.
568→Suggested command:
569→- pnpm paperclipai allowed-hostname <host>
570→Then verify with: curl -fsS <base-url>/api/health`;
571→
572→  const resolutionLine = resolutionTestUrl
573→    ? `\nYou MUST test Paperclip-to-gateway reachability, call: ${resolutionTestUrl}?url=<urlencoded-gateway-url> (using the hostname that worked above). Do not assume your 172.x is necessarily reachable from Paperclip. Test it. `
574→    : "";
575→
576→  return `You're invited to join a Paperclip organization.
577→
578→The URLs you should try are:
579→${candidateList}
580→
581→Connectivity guidance:
582→If you are running on a different machine than Paperclip, Paperclip must be reachable at one of the hostnames used above.
583→Verify the hostname works from your runtime with: GET <base-url>/api/health
584→
585→${connectivityBlock}
586→
587→For your "agentName", just use your own agent name (OpenClaw or whatever your name is) and send it directly.
588→You also need to send a gateway URL that Paperclip can access. Check your config and include that URL.${resolutionLine}
589→
590→---
591→
592→This onboarding flow is for OpenClaw Gateway.
593→When you submit the join request, use:
594→- \`adapterType: "openclaw_gateway"\`
595→- \`agentDefaultsPayload.url\` as your \`ws://\` or \`wss://\` gateway URL
596→- \`agentDefaultsPayload.headers["x-openclaw-token"]\` with your gateway token
597→- (legacy accepted) \`agentDefaultsPayload.headers["x-openclaw-auth"]\`
598→- Keep device auth enabled (recommended). If \`devicePrivateKeyPem\` is omitted, Paperclip will generate and persist one during join so pairing approvals remain stable.
599→- Only use \`disableDeviceAuth=true\` for special environments where pairing cannot be completed.
600→
601→Do NOT use \`/v1/responses\` or \`/hooks/*\` in this join flow.
602→
603→Before you do anything, please respond to your user that you understand the instructions and you're going to work on them. Then do the step above in another session called "paperclip-onboarding" and then tell your user when you're done. Update your user in intermediate steps along the way so they know what's going on.
604→
605→Then after you've connected to Paperclip (exchanged keys etc.) you MUST review and follow the onboarding instructions in onboarding.txt they give you.
606→
607→`;
608→}
609→
610→function buildCandidateOnboardingUrls(input: AgentSnippetInput): string[] {
611→  const candidates = (input.connectionCandidates ?? [])
612→    .map((candidate) => candidate.trim())
613→    .filter(Boolean);
614→  const urls = new Set<string>();
615→  let onboardingUrl: URL | null = null;
616→
617→  try {
618→    onboardingUrl = new URL(input.onboardingTextUrl);
619→    urls.add(onboardingUrl.toString());
620→  } catch {
621→    const trimmed = input.onboardingTextUrl.trim();
622→    if (trimmed) {
623→      urls.add(trimmed);
624→    }
625→  }
626→
627→  if (!onboardingUrl) {
628→    for (const candidate of candidates) {
629→      urls.add(candidate);
630→    }
631→    return Array.from(urls);
632→  }
633→
634→  const onboardingPath = `${onboardingUrl.pathname}${onboardingUrl.search}`;
635→  for (const candidate of candidates) {
636→    try {
637→      const base = new URL(candidate);
638→      urls.add(`${base.origin}${onboardingPath}`);
639→    } catch {
640→      urls.add(candidate);
641→    }
642→  }
643→
644→  return Array.from(urls);
645→}
646→
647→function buildResolutionTestUrl(input: AgentSnippetInput): string | null {
648→  const explicit = input.testResolutionUrl?.trim();
649→  if (explicit) return explicit;
650→
651→  try {
652→    const onboardingUrl = new URL(input.onboardingTextUrl);
653→    const testPath = onboardingUrl.pathname.replace(
654→      /\/onboarding\.txt$/,
655→      "/test-resolution"
656→    );
657→    return `${onboardingUrl.origin}${testPath}`;
658→  } catch {
659→    return null;
660→  }
661→}
