  10→import { cn } from "@/lib/utils";
  11→import { Input } from "@/components/ui/input";
  12→import { Textarea } from "@/components/ui/textarea";
  13→import { Label } from "@/components/ui/label";
  14→import { Checkbox } from "@/components/ui/checkbox";
  15→import { Button } from "@/components/ui/button";
  16→import {
  17→  Select,
  18→  SelectContent,
  19→  SelectItem,
  20→  SelectTrigger,
  21→  SelectValue,
  22→} from "@/components/ui/select";
  23→
  24→// ---------------------------------------------------------------------------
  25→// Constants
  26→// ---------------------------------------------------------------------------
  27→
  28→/**
  29→ * Threshold for string length above which a Textarea is used instead of a standard Input.
  30→ */
  31→const TEXTAREA_THRESHOLD = 200;
  32→
  33→// ---------------------------------------------------------------------------
  34→// Types
  35→// ---------------------------------------------------------------------------
  36→
  37→/**
  38→ * Subset of JSON Schema properties we understand for form rendering.
  39→ * We intentionally keep this loose (`Record<string, unknown>`) at the top
  40→ * level to match the `JsonSchema` type in shared, but narrow internally.
  41→ */
  42→export interface JsonSchemaNode {
  43→  type?: string | string[];
  44→  title?: string;
  45→  description?: string;
  46→  default?: unknown;
  47→  enum?: unknown[];
  48→  const?: unknown;
  49→  format?: string;
  50→
  51→  // String constraints
  52→  minLength?: number;
  53→  maxLength?: number;
  54→  pattern?: string;
  55→
  56→  // Number constraints
  57→  minimum?: number;
  58→  maximum?: number;
  59→  exclusiveMinimum?: number;
  60→  exclusiveMaximum?: number;
  61→  multipleOf?: number;
  62→
  63→  // Object
  64→  properties?: Record<string, JsonSchemaNode>;
  65→  required?: string[];
  66→  additionalProperties?: boolean | JsonSchemaNode;
  67→
  68→  // Array
  69→  items?: JsonSchemaNode;
  70→  minItems?: number;
  71→  maxItems?: number;
  72→
  73→  // Metadata
  74→  readOnly?: boolean;
  75→  writeOnly?: boolean;
  76→
  77→  // Allow extra keys
  78→  [key: string]: unknown;
  79→}
  80→
  81→export interface JsonSchemaFormProps {
  82→  /** The JSON Schema to render. */
  83→  schema: JsonSchemaNode;
  84→  /** Current form values. */
  85→  values: Record<string, unknown>;
  86→  /** Called whenever any field value changes. */
  87→  onChange: (values: Record<string, unknown>) => void;
  88→  /** Validation errors keyed by JSON pointer path (e.g. "/apiKey"). */
  89→  errors?: Record<string, string>;
  90→  /** If true, all fields are disabled. */
  91→  disabled?: boolean;
  92→  /** Additional CSS class for the root container. */
  93→  className?: string;
  94→}
  95→
  96→// ---------------------------------------------------------------------------
  97→// Helpers
  98→// ---------------------------------------------------------------------------
  99→
 100→/** Resolve the primary type string from a schema node. */
 101→export function resolveType(schema: JsonSchemaNode): string {
 102→  if (schema.enum) return "enum";
 103→  if (schema.const !== undefined) return "const";
 104→  if (schema.format === "secret-ref") return "secret-ref";
 105→  if (Array.isArray(schema.type)) {
 106→    // Use the first non-null type
 107→    return schema.type.find((t) => t !== "null") ?? "string";
 108→  }
 109→  return schema.type ?? "string";
 110→}
 111→
 112→/** Human-readable label from schema title or property key. */
 113→export function labelFromKey(key: string, schema: JsonSchemaNode): string {
 114→  if (schema.title) return schema.title;
 115→  // Convert camelCase / snake_case to Title Case
 116→  return key
 117→    .replace(/([a-z])([A-Z])/g, "$1 $2")
 118→    .replace(/[_-]+/g, " ")
 119→    .replace(/\b\w/g, (c) => c.toUpperCase());
 120→}
 121→
 122→/** Produce a sensible default value for a schema node. */
 123→export function getDefaultForSchema(schema: JsonSchemaNode): unknown {
 124→  if (schema.default !== undefined) return schema.default;
 125→
 126→  const type = resolveType(schema);
 127→  switch (type) {
 128→    case "string":
 129→    case "secret-ref":
 130→      return "";
 131→    case "number":
 132→    case "integer":
 133→      return schema.minimum ?? 0;
 134→    case "boolean":
 135→      return false;
 136→    case "enum":
 137→      return schema.enum?.[0] ?? "";
 138→    case "array":
 139→      return [];
 140→    case "object": {
 141→      if (!schema.properties) return {};
 142→      const obj: Record<string, unknown> = {};
 143→      for (const [key, propSchema] of Object.entries(schema.properties)) {
 144→        obj[key] = getDefaultForSchema(propSchema);
 145→      }
 146→      return obj;
 147→    }
 148→    default:
 149→      return "";
 150→  }
 151→}
 152→
 153→/** Validate a single field value against schema constraints. Returns error string or null. */
 154→export function validateField(
 155→  value: unknown,
 156→  schema: JsonSchemaNode,
 157→  isRequired: boolean,
 158→): string | null {
 159→  const type = resolveType(schema);
 160→
 161→  // Required check
 162→  if (isRequired && (value === undefined || value === null || value === "")) {
 163→    return "This field is required";
 164→  }
 165→
 166→  // Skip further validation if empty and not required
 167→  if (value === undefined || value === null || value === "") return null;
 168→
 169→  if (type === "string" || type === "secret-ref") {
 170→    const str = String(value);
 171→    if (schema.minLength != null && str.length < schema.minLength) {
 172→      return `Must be at least ${schema.minLength} characters`;
 173→    }
 174→    if (schema.maxLength != null && str.length > schema.maxLength) {
 175→      return `Must be at most ${schema.maxLength} characters`;
 176→    }
 177→    if (schema.pattern) {
 178→      // Guard against ReDoS: reject overly complex patterns from plugin JSON Schemas.
 179→      // Limit pattern length and run the regex with a defensive try/catch.
 180→      const MAX_PATTERN_LENGTH = 512;
 181→      if (schema.pattern.length <= MAX_PATTERN_LENGTH) {
 182→        try {
 183→          const re = new RegExp(schema.pattern);
 184→          if (!re.test(str)) {
 185→            return `Must match pattern: ${schema.pattern}`;
 186→          }
 187→        } catch {
 188→          // Invalid regex in schema — skip
 189→        }
 190→      }
 191→    }
 192→  }
 193→
 194→  if (type === "number" || type === "integer") {
 195→    const num = Number(value);
 196→    if (isNaN(num)) return "Must be a valid number";
 197→    if (schema.minimum != null && num < schema.minimum) {
 198→      return `Must be at least ${schema.minimum}`;
 199→    }
 200→    if (schema.maximum != null && num > schema.maximum) {
 201→      return `Must be at most ${schema.maximum}`;
 202→    }
 203→    if (schema.exclusiveMinimum != null && num <= schema.exclusiveMinimum) {
 204→      return `Must be greater than ${schema.exclusiveMinimum}`;
 205→    }
 206→    if (schema.exclusiveMaximum != null && num >= schema.exclusiveMaximum) {
 207→      return `Must be less than ${schema.exclusiveMaximum}`;
 208→    }
 209→    if (type === "integer" && !Number.isInteger(num)) {
 210→      return "Must be a whole number";
 211→    }
 212→    if (schema.multipleOf != null && num % schema.multipleOf !== 0) {
 213→      return `Must be a multiple of ${schema.multipleOf}`;
 214→    }
 215→  }
 216→
 217→  if (type === "array") {
 218→    const arr = value as unknown[];
 219→    if (schema.minItems != null && arr.length < schema.minItems) {
 220→      return `Must have at least ${schema.minItems} items`;
 221→    }
 222→    if (schema.maxItems != null && arr.length > schema.maxItems) {
 223→      return `Must have at most ${schema.maxItems} items`;
 224→    }
 225→  }
 226→
 227→  return null;
 228→}
 229→
 230→/** Public API for validation */
 231→export function validateJsonSchemaForm(
 232→  schema: JsonSchemaNode,
 233→  values: Record<string, unknown>,
 234→  path: string[] = [],
 235→): Record<string, string> {
 236→  const errors: Record<string, string> = {};
 237→  const properties = schema.properties ?? {};
 238→  const requiredFields = new Set(schema.required ?? []);
 239→
 240→  for (const [key, propSchema] of Object.entries(properties)) {
 241→    const fieldPath = [...path, key];
 242→    const errorKey = `/${fieldPath.join("/")}`;
 243→    const value = values[key];
 244→    const isRequired = requiredFields.has(key);
 245→    const type = resolveType(propSchema);
 246→
 247→    // Per-field validation
 248→    const fieldErr = validateField(value, propSchema, isRequired);
 249→    if (fieldErr) {
 250→      errors[errorKey] = fieldErr;
 251→    }
 252→
 253→    // Recurse into objects
 254→    if (type === "object" && propSchema.properties && typeof value === "object" && value !== null) {
 255→      Object.assign(
 256→        errors,
 257→        validateJsonSchemaForm(propSchema, value as Record<string, unknown>, fieldPath),
 258→      );
 259→    }
 260→
 261→    // Recurse into arrays
 262→    if (type === "array" && propSchema.items && Array.isArray(value)) {
 263→      const itemSchema = propSchema.items as JsonSchemaNode;
 264→      const isObjectItem = resolveType(itemSchema) === "object";
 265→
 266→      value.forEach((item, index) => {
 267→        const itemPath = [...fieldPath, String(index)];
 268→        const itemErrorKey = `/${itemPath.join("/")}`;
 269→
 270→        if (isObjectItem) {
 271→          Object.assign(
 272→            errors,
 273→            validateJsonSchemaForm(
 274→              itemSchema,
 275→              item as Record<string, unknown>,
 276→              itemPath,
 277→            ),
 278→          );
 279→        } else {
 280→          const itemErr = validateField(item, itemSchema, false);
 281→          if (itemErr) {
 282→            errors[itemErrorKey] = itemErr;
 283→          }
 284→        }
 285→      });
 286→    }
 287→  }
 288→
 289→  return errors;
 290→}
 291→
 292→/** Public API for default values */
 293→export function getDefaultValues(schema: JsonSchemaNode): Record<string, unknown> {
 294→  const result: Record<string, unknown> = {};
 295→  const properties = schema.properties ?? {};
 296→
 297→  for (const [key, propSchema] of Object.entries(properties)) {
 298→    const def = getDefaultForSchema(propSchema);
 299→    if (def !== undefined) {
 300→      result[key] = def;
 301→    }
 302→  }
 303→
 304→  return result;
 305→}
 306→
 307→// ---------------------------------------------------------------------------
 308→// Internal Components
 309→// ---------------------------------------------------------------------------
 310→
 311→interface FieldWrapperProps {
 312→  label: string;
 313→  description?: string;
 314→  required?: boolean;
 315→  error?: string;
 316→  disabled?: boolean;
 317→  children: React.ReactNode;
 318→}
 319→
 320→/**
 321→ * Common wrapper for form fields that handles labels, descriptions, and error messages.
 322→ */
 323→const FieldWrapper = React.memo(({
 324→  label,
 325→  description,
 326→  required,
 327→  error,
 328→  disabled,
 329→  children,
 330→}: FieldWrapperProps) => {
 331→  return (
 332→    <div className={cn("space-y-2", disabled && "opacity-60")}>
 333→      <div className="flex items-center justify-between">
 334→        {label && (
 335→          <Label className="text-sm font-medium">
 336→            {label}
 337→            {required && <span className="ml-1 text-destructive">*</span>}
 338→          </Label>
 339→        )}
 340→      </div>
 341→      {children}
 342→      {description && (
 343→        <p className="text-[12px] text-muted-foreground leading-relaxed">
 344→          {description}
 345→        </p>
 346→      )}
 347→      {error && (
 348→        <p className="text-[12px] font-medium text-destructive">{error}</p>
 349→      )}
 350→    </div>
 351→  );
 352→});
 353→
 354→FieldWrapper.displayName = "FieldWrapper";
 355→
 356→interface FormFieldProps {
 357→  propSchema: JsonSchemaNode;
 358→  value: unknown;
 359→  onChange: (val: unknown) => void;
 360→  error?: string;
 361→  disabled?: boolean;
 362→  label: string;
 363→  isRequired?: boolean;
 364→  errors: Record<string, string>; // needed for recursion
 365→  path: string; // needed for recursion error filtering
 366→}
 367→
 368→/**
 369→ * Specialized field for boolean (checkbox) values.
 370→ */
 371→const BooleanField = React.memo(({
 372→  id,
 373→  value,
 374→  onChange,
 375→  disabled,
 376→  label,
 377→  isRequired,
 378→  description,
 379→  error,
 380→}: {
 381→  id: string;
 382→  value: unknown;
 383→  onChange: (val: unknown) => void;
 384→  disabled: boolean;
 385→  label: string;
 386→  isRequired?: boolean;
 387→  description?: string;
 388→  error?: string;
 389→}) => (
 390→  <div className="flex items-start space-x-3 space-y-0">
 391→    <Checkbox
 392→      id={id}
 393→      checked={!!value}
 394→      onCheckedChange={onChange}
 395→      disabled={disabled}
 396→    />
 397→    <div className="grid gap-1.5 leading-none">
 398→      {label && (
 399→        <Label
 400→          htmlFor={id}
 401→          className="text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70"
 402→        >
 403→          {label}
 404→          {isRequired && <span className="ml-1 text-destructive">*</span>}
 405→        </Label>
 406→      )}
 407→      {description && (
 408→        <p className="text-xs text-muted-foreground">{description}</p>
 409→      )}
 410→      {error && (
 411→        <p className="text-xs font-medium text-destructive">{error}</p>
 412→      )}
 413→    </div>
 414→  </div>
 415→));
 416→
 417→BooleanField.displayName = "BooleanField";
 418→
 419→/**
 420→ * Specialized field for enum (select) values.
 421→ */
 422→const EnumField = React.memo(({
 423→  value,
 424→  onChange,
 425→  disabled,
 426→  label,
 427→  isRequired,
 428→  description,
 429→  error,
 430→  options,
 431→}: {
 432→  value: unknown;
 433→  onChange: (val: unknown) => void;
 434→  disabled: boolean;
 435→  label: string;
 436→  isRequired?: boolean;
 437→  description?: string;
 438→  error?: string;
 439→  options: unknown[];
 440→}) => (
 441→  <FieldWrapper
 442→    label={label}
 443→    description={description}
 444→    required={isRequired}
 445→    error={error}
 446→    disabled={disabled}
 447→  >
 448→    <Select
 449→      value={String(value ?? "")}
 450→      onValueChange={onChange}
 451→      disabled={disabled}
 452→    >
 453→      <SelectTrigger className="w-full">
 454→        <SelectValue placeholder="Select an option" />
 455→      </SelectTrigger>
 456→      <SelectContent>
 457→        {options.map((option) => (
 458→          <SelectItem key={String(option)} value={String(option)}>
 459→            {String(option)}
 460→          </SelectItem>
 461→        ))}
 462→      </SelectContent>
 463→    </Select>
 464→  </FieldWrapper>
 465→));
 466→
 467→EnumField.displayName = "EnumField";
 468→
 469→/**
 470→ * Specialized field for secret-ref values, providing a toggleable password input.
 471→ */
 472→const SecretField = React.memo(({
 473→  value,
 474→  onChange,
 475→  disabled,
 476→  label,
 477→  isRequired,
 478→  description,
 479→  error,
 480→  defaultValue,
 481→}: {
 482→  value: unknown;
 483→  onChange: (val: unknown) => void;
 484→  disabled: boolean;
 485→  label: string;
 486→  isRequired?: boolean;
 487→  description?: string;
 488→  error?: string;
 489→  defaultValue?: unknown;
 490→}) => {
 491→  const [isVisible, setIsVisible] = useState(false);
 492→  return (
 493→    <FieldWrapper
 494→      label={label}
 495→      description={
 496→        description ||
 497→        "This secret is stored securely via the Paperclip secret provider."
 498→      }
 499→      required={isRequired}
 500→      error={error}
 501→      disabled={disabled}
 502→    >
 503→      <div className="relative">
 504→        <Input
 505→          type={isVisible ? "text" : "password"}
 506→          value={String(value ?? "")}
 507→          onChange={(e) => onChange(e.target.value)}
 508→          placeholder={String(defaultValue ?? "")}
 509→          disabled={disabled}
 510→          className="pr-10"
 511→          aria-invalid={!!error}
 512→        />
 513→        <Button
 514→          type="button"
 515→          variant="ghost"
 516→          size="sm"
 517→          className="absolute right-0 top-0 h-full px-3 py-2 hover:bg-transparent"
 518→          onClick={() => setIsVisible(!isVisible)}
 519→          disabled={disabled}
 520→        >
 521→          {isVisible ? (
 522→            <EyeOff className="h-4 w-4 text-muted-foreground" />
 523→          ) : (
 524→            <Eye className="h-4 w-4 text-muted-foreground" />
 525→          )}
 526→          <span className="sr-only">
 527→            {isVisible ? "Hide secret" : "Show secret"}
 528→          </span>
 529→        </Button>
 530→      </div>
 531→    </FieldWrapper>
 532→  );
 533→});
 534→
 535→SecretField.displayName = "SecretField";
 536→
 537→/**
 538→ * Specialized field for numeric (number/integer) values.
 539→ */
 540→const NumberField = React.memo(({
 541→  value,
 542→  onChange,
 543→  disabled,
 544→  label,
 545→  isRequired,
 546→  description,
 547→  error,
 548→  defaultValue,
 549→  type,
 550→}: {
 551→  value: unknown;
 552→  onChange: (val: unknown) => void;
 553→  disabled: boolean;
 554→  label: string;
 555→  isRequired?: boolean;
 556→  description?: string;
 557→  error?: string;
 558→  defaultValue?: unknown;
 559→  type: "number" | "integer";
 560→}) => (
 561→  <FieldWrapper
 562→    label={label}
 563→    description={description}
 564→    required={isRequired}
 565→    error={error}
 566→    disabled={disabled}
 567→  >
 568→    <Input
 569→      type="number"
 570→      step={type === "integer" ? "1" : "any"}
 571→      value={value !== undefined ? String(value) : ""}
 572→      onChange={(e) => {
 573→        const val = e.target.value;
