 577→      disabled={disabled}
 578→      aria-invalid={!!error}
 579→    />
 580→  </FieldWrapper>
 581→));
 582→
 583→NumberField.displayName = "NumberField";
 584→
 585→/**
 586→ * Specialized field for string values, rendering either an Input or Textarea based on length or format.
 587→ */
 588→const StringField = React.memo(({
 589→  value,
 590→  onChange,
 591→  disabled,
 592→  label,
 593→  isRequired,
 594→  description,
 595→  error,
 596→  defaultValue,
 597→  format,
 598→  maxLength,
 599→}: {
 600→  value: unknown;
 601→  onChange: (val: unknown) => void;
 602→  disabled: boolean;
 603→  label: string;
 604→  isRequired?: boolean;
 605→  description?: string;
 606→  error?: string;
 607→  defaultValue?: unknown;
 608→  format?: string;
 609→  maxLength?: number;
 610→}) => {
 611→  const isTextArea = format === "textarea" || (maxLength && maxLength > TEXTAREA_THRESHOLD);
 612→  return (
 613→    <FieldWrapper
 614→      label={label}
 615→      description={description}
 616→      required={isRequired}
 617→      error={error}
 618→      disabled={disabled}
 619→    >
 620→      {isTextArea ? (
 621→        <Textarea
 622→          value={String(value ?? "")}
 623→          onChange={(e) => onChange(e.target.value)}
 624→          placeholder={String(defaultValue ?? "")}
 625→          disabled={disabled}
 626→          className="min-h-[100px]"
 627→          aria-invalid={!!error}
 628→        />
 629→      ) : (
 630→        <Input
 631→          type="text"
 632→          value={String(value ?? "")}
 633→          onChange={(e) => onChange(e.target.value)}
 634→          placeholder={String(defaultValue ?? "")}
 635→          disabled={disabled}
 636→          aria-invalid={!!error}
 637→        />
 638→      )}
 639→    </FieldWrapper>
 640→  );
 641→});
 642→
 643→StringField.displayName = "StringField";
 644→
 645→/**
 646→ * Specialized field for array values, handling dynamic addition and removal of items.
 647→ */
 648→const ArrayField = React.memo(({
 649→  propSchema,
 650→  value,
 651→  onChange,
 652→  error,
 653→  disabled,
 654→  label,
 655→  errors,
 656→  path,
 657→}: {
 658→  propSchema: JsonSchemaNode;
 659→  value: unknown;
 660→  onChange: (val: unknown) => void;
 661→  error?: string;
 662→  disabled: boolean;
 663→  label: string;
 664→  errors: Record<string, string>;
 665→  path: string;
 666→}) => {
 667→  const items = Array.isArray(value) ? value : [];
 668→  const itemSchema = propSchema.items as JsonSchemaNode;
 669→  const isComplex = resolveType(itemSchema) === "object";
 670→
 671→  return (
 672→    <div className="space-y-4">
 673→      <div className="flex items-center justify-between">
 674→        <div>
 675→          <Label className="text-sm font-medium">{label}</Label>
 676→          {propSchema.description && (
 677→            <p className="text-xs text-muted-foreground">
 678→              {propSchema.description}
 679→            </p>
 680→          )}
 681→        </div>
 682→        <Button
 683→          type="button"
 684→          variant="outline"
 685→          size="sm"
 686→          disabled={
 687→            disabled ||
 688→            (propSchema.maxItems !== undefined &&
 689→              items.length >= (propSchema.maxItems as number))
 690→          }
 691→          onClick={() => {
 692→            const newItem = getDefaultForSchema(itemSchema);
 693→            onChange([...items, newItem]);
 694→          }}
 695→        >
 696→          <Plus className="mr-2 h-4 w-4" />
 697→          {isComplex ? "Add item" : "Add"}
 698→        </Button>
 699→      </div>
 700→
 701→      <div className="space-y-3">
 702→        {items.map((item, index) => (
 703→          <div
 704→            key={index}
 705→            className="group relative flex items-start space-x-2 rounded-lg border p-3"
 706→          >
 707→            <div className="flex-1">
 708→              <div className="mb-2 text-xs font-medium text-muted-foreground">
 709→                Item {index + 1}
 710→              </div>
 711→              <FormField
 712→                propSchema={itemSchema}
 713→                value={item}
 714→                label=""
 715→                path={`${path}/${index}`}
 716→                onChange={(newVal) => {
 717→                  const newItems = [...items];
 718→                  newItems[index] = newVal;
 719→                  onChange(newItems);
 720→                }}
 721→                disabled={disabled}
 722→                errors={errors}
 723→              />
 724→            </div>
 725→            <Button
 726→              type="button"
 727→              variant="ghost"
 728→              size="icon"
 729→              className="h-8 w-8 text-muted-foreground hover:text-destructive"
 730→              disabled={
 731→                disabled ||
 732→                (propSchema.minItems !== undefined &&
 733→                  items.length <= (propSchema.minItems as number))
 734→              }
 735→              onClick={() => {
 736→                const newItems = [...items];
 737→                newItems.splice(index, 1);
 738→                onChange(newItems);
 739→              }}
 740→            >
 741→              <Trash2 className="h-4 w-4" />
 742→              <span className="sr-only">Remove item</span>
 743→            </Button>
 744→          </div>
 745→        ))}
 746→        {items.length === 0 && (
 747→          <div className="rounded-lg border border-dashed p-4 text-center text-xs text-muted-foreground">
 748→            No items added yet.
 749→          </div>
 750→        )}
 751→      </div>
 752→      {error && (
 753→        <p className="text-xs font-medium text-destructive">{error}</p>
 754→      )}
 755→    </div>
 756→  );
 757→});
 758→
 759→ArrayField.displayName = "ArrayField";
 760→
 761→/**
 762→ * Specialized field for object values, handling recursive rendering of nested properties.
 763→ */
 764→const ObjectField = React.memo(({
 765→  propSchema,
 766→  value,
 767→  onChange,
 768→  disabled,
 769→  label,
 770→  errors,
 771→  path,
 772→}: {
 773→  propSchema: JsonSchemaNode;
 774→  value: unknown;
 775→  onChange: (val: unknown) => void;
 776→  disabled: boolean;
 777→  label: string;
 778→  errors: Record<string, string>;
 779→  path: string;
 780→}) => {
 781→  const [isCollapsed, setIsCollapsed] = useState(false);
 782→  const handleObjectChange = (newVal: Record<string, unknown>) => {
 783→    onChange(newVal);
 784→  };
 785→
 786→  return (
 787→    <div className="space-y-3 rounded-lg border p-4">
 788→      <button
 789→        type="button"
 790→        className="flex w-full items-center justify-between"
 791→        onClick={() => setIsCollapsed(!isCollapsed)}
 792→      >
 793→        <div className="text-left">
 794→          <Label className="cursor-pointer text-sm font-semibold">
 795→            {label}
 796→          </Label>
 797→          {propSchema.description && (
 798→            <p className="text-xs text-muted-foreground">
 799→              {propSchema.description}
 800→            </p>
 801→          )}
 802→        </div>
 803→        {isCollapsed ? (
 804→          <ChevronRight className="h-4 w-4 text-muted-foreground" />
 805→        ) : (
 806→          <ChevronDown className="h-4 w-4 text-muted-foreground" />
 807→        )}
 808→      </button>
 809→
 810→      {!isCollapsed && (
 811→        <div className="pt-2">
 812→          <JsonSchemaForm
 813→            schema={propSchema}
 814→            values={(value as Record<string, unknown>) ?? {}}
 815→            onChange={handleObjectChange}
 816→            disabled={disabled}
 817→            errors={Object.fromEntries(
 818→              Object.entries(errors)
 819→                .filter(([errPath]) => errPath.startsWith(`${path}/`))
 820→                .map(([errPath, err]) => [errPath.replace(path, ""), err]),
 821→            )}
 822→          />
 823→        </div>
 824→      )}
 825→    </div>
 826→  );
 827→});
 828→
 829→ObjectField.displayName = "ObjectField";
 830→
 831→/**
 832→ * Orchestrator component that selects and renders the appropriate field type based on the schema node.
 833→ */
 834→const FormField = React.memo(({
 835→  propSchema,
 836→  value,
 837→  onChange,
 838→  error,
 839→  disabled,
 840→  label,
 841→  isRequired,
 842→  errors,
 843→  path,
 844→}: FormFieldProps) => {
 845→  const type = resolveType(propSchema);
 846→  const isReadOnly = disabled || propSchema.readOnly === true;
 847→
 848→  switch (type) {
 849→    case "boolean":
 850→      return (
 851→        <BooleanField
 852→          id={path}
 853→          value={value}
 854→          onChange={onChange}
 855→          disabled={isReadOnly}
 856→          label={label}
 857→          isRequired={isRequired}
 858→          description={propSchema.description}
 859→          error={error}
 860→        />
 861→      );
 862→
 863→    case "enum":
 864→      return (
 865→        <EnumField
 866→          value={value}
 867→          onChange={onChange}
 868→          disabled={isReadOnly}
 869→          label={label}
 870→          isRequired={isRequired}
 871→          description={propSchema.description}
 872→          error={error}
 873→          options={propSchema.enum ?? []}
 874→        />
 875→      );
 876→
 877→    case "secret-ref":
 878→      return (
 879→        <SecretField
 880→          value={value}
 881→          onChange={onChange}
 882→          disabled={isReadOnly}
 883→          label={label}
 884→          isRequired={isRequired}
 885→          description={propSchema.description}
 886→          error={error}
 887→          defaultValue={propSchema.default}
 888→        />
 889→      );
 890→
 891→    case "number":
 892→    case "integer":
 893→      return (
 894→        <NumberField
 895→          value={value}
 896→          onChange={onChange}
 897→          disabled={isReadOnly}
 898→          label={label}
 899→          isRequired={isRequired}
 900→          description={propSchema.description}
 901→          error={error}
 902→          defaultValue={propSchema.default}
 903→          type={type as "number" | "integer"}
 904→        />
 905→      );
 906→
 907→    case "array":
 908→      return (
 909→        <ArrayField
 910→          propSchema={propSchema}
 911→          value={value}
 912→          onChange={onChange}
 913→          error={error}
 914→          disabled={isReadOnly}
 915→          label={label}
 916→          errors={errors}
 917→          path={path}
 918→        />
 919→      );
 920→
 921→    case "object":
 922→      return (
 923→        <ObjectField
 924→          propSchema={propSchema}
 925→          value={value}
 926→          onChange={onChange}
 927→          disabled={isReadOnly}
 928→          label={label}
 929→          errors={errors}
 930→          path={path}
 931→        />
 932→      );
 933→
 934→    default: // string
 935→      return (
 936→        <StringField
 937→          value={value}
 938→          onChange={onChange}
 939→          disabled={isReadOnly}
 940→          label={label}
 941→          isRequired={isRequired}
 942→          description={propSchema.description}
 943→          error={error}
 944→          defaultValue={propSchema.default}
 945→          format={propSchema.format}
 946→          maxLength={propSchema.maxLength}
 947→        />
 948→      );
 949→  }
 950→});
 951→
 952→FormField.displayName = "FormField";
 953→
 954→// ---------------------------------------------------------------------------
 955→// Main Component
 956→// ---------------------------------------------------------------------------
 957→
 958→/**
 959→ * Main JsonSchemaForm component.
 960→ * Renders a form based on a subset of JSON Schema specification.
 961→ * Supports primitive types, enums, secrets, objects, and arrays with recursion.
 962→ */
 963→export function JsonSchemaForm({
 964→  schema,
 965→  values,
 966→  onChange,
 967→  errors = {},
 968→  disabled,
 969→  className,
 970→}: JsonSchemaFormProps) {
 971→  const type = resolveType(schema);
 972→
 973→  const handleRootScalarChange = useCallback((newVal: unknown) => {
 974→    // If root is a scalar, values IS the value
 975→    onChange(newVal as Record<string, unknown>);
 976→  }, [onChange]);
 977→
 978→  // If it's a scalar at root, render a single FormField
 979→  if (type !== "object") {
 980→    return (
 981→      <div className={className}>
 982→        <FormField
 983→          propSchema={schema}
 984→          value={values}
 985→          label=""
 986→          path=""
 987→          onChange={handleRootScalarChange}
 988→          disabled={disabled}
 989→          errors={errors}
 990→        />
 991→      </div>
 992→    );
 993→  }
 994→
 995→  // Memoize to avoid re-renders when parent provides new object references
 996→  const properties = useMemo(() => schema.properties ?? {}, [schema.properties]);
 997→  const requiredFields = useMemo(
 998→    () => new Set(schema.required ?? []),
 999→    [schema.required],
1000→  );
1001→
1002→  const handleFieldChange = useCallback(
1003→    (key: string, value: unknown) => {
1004→      onChange({ ...values, [key]: value });
1005→    },
1006→    [onChange, values],
1007→  );
1008→
1009→  if (Object.keys(properties).length === 0) {
1010→    return (
1011→      <div
1012→        className={cn(
1013→          "py-4 text-center text-sm text-muted-foreground",
1014→          className,
1015→        )}
1016→      >
1017→        No configuration options available.
1018→      </div>
1019→    );
1020→  }
1021→
1022→  return (
1023→    <div className={cn("space-y-6", className)}>
1024→      {Object.entries(properties).map(([key, propSchema]) => {
1025→        const value = values[key];
1026→        const isRequired = requiredFields.has(key);
1027→        const error = errors[`/${key}`];
1028→        const label = labelFromKey(key, propSchema);
1029→        const path = `/${key}`;
1030→
1031→        return (
1032→          <FormField
1033→            key={key}
1034→            propSchema={propSchema}
1035→            value={value}
1036→            onChange={(val) => handleFieldChange(key, val)}
1037→            error={error}
1038→            disabled={disabled}
1039→            label={label}
1040→            isRequired={isRequired}
1041→            errors={errors}
1042→            path={path}
1043→          />
1044→        );
1045→      })}
1046→    </div>
1047→  );
1048→}
