185→/**
186→ * Specialized field for selecting a company by ID.
187→ * Rendered automatically when a plugin schema field key is "companyId".
188→ */
189→const CompanySelectField = React.memo(({
190→  value,
191→  onChange,
192→  disabled,
193→  label,
194→  isRequired,
195→  description,
196→  error,
197→}: {
198→  value: unknown;
199→  onChange: (val: unknown) => void;
200→  disabled: boolean;
201→  label: string;
202→  isRequired?: boolean;
203→  description?: string;
204→  error?: string;
205→}) => {
206→  const { companies, selectedCompanyId } = useCompany();
207→  const activeCompanies = useMemo(
208→    () => companies.filter((c) => c.status !== "archived"),
209→    [companies],
210→  );
211→
212→  // Value priority chain:
213→  // 1. Saved value matching a valid (non-archived) company → keep it
214→  // 2. Empty/null or references archived/deleted company → default to current company
215→  // 3. Single company → auto-select
216→  const currentValue = useMemo(() => {
217→    const strVal = value ? String(value) : "";
218→    if (strVal && activeCompanies.some((c) => c.id === strVal)) {
219→      return strVal;
220→    }
221→    if (selectedCompanyId && activeCompanies.some((c) => c.id === selectedCompanyId)) {
222→      return selectedCompanyId;
223→    }
224→    if (activeCompanies.length === 1) {
225→      return activeCompanies[0]!.id;
226→    }
227→    return "";
228→  }, [value, activeCompanies, selectedCompanyId]);
229→
230→  // Auto-set value when it differs from what's stored
231→  useEffect(() => {
232→    if (currentValue && currentValue !== String(value ?? "")) {
233→      onChange(currentValue);
234→    }
235→  }, [currentValue]); // eslint-disable-line react-hooks/exhaustive-deps
236→
237→  if (activeCompanies.length === 0) {
238→    return (
239→      <FieldWrapper
240→        label={label}
241→        description={description}
242→        required={isRequired}
243→        error={error}
244→        disabled
245→      >
246→        <Select disabled>
247→          <SelectTrigger className="w-full">
248→            <SelectValue placeholder="No companies available" />
249→          </SelectTrigger>
250→        </Select>
251→      </FieldWrapper>
252→    );
253→  }
254→
255→  return (
256→    <FieldWrapper
257→      label={label}
258→      description={description}
259→      required={isRequired}
260→      error={error}
261→      disabled={disabled}
262→    >
263→      <Select
264→        value={currentValue}
265→        onValueChange={onChange}
266→        disabled={disabled}
267→      >
268→        <SelectTrigger className="w-full">
269→          <SelectValue placeholder="Select a company" />
270→        </SelectTrigger>
271→        <SelectContent>
272→          {activeCompanies.map((company) => (
273→            <SelectItem key={company.id} value={company.id}>
274→              {company.name}
275→              {company.issuePrefix ? ` (${company.issuePrefix})` : ""}
276→            </SelectItem>
277→          ))}
278→        </SelectContent>
279→      </Select>
280→    </FieldWrapper>
281→  );
282→});
283→
