580→function buildAgentSnippet(input: AgentSnippetInput) {
581→  const candidateUrls = buildCandidateOnboardingUrls(input);
582→  const resolutionTestUrl = buildResolutionTestUrl(input);
583→
584→  const candidateList =
585→    candidateUrls.length > 0
586→      ? candidateUrls.map((u) => `- ${u}`).join("\n")
587→      : "- (No candidate URLs available yet.)";
588→
589→  const connectivityBlock =
590→    candidateUrls.length === 0
591→      ? `No candidate URLs are available. Ask your user to configure a reachable hostname in Paperclip, then retry.
592→Suggested steps:
593→- choose a hostname that resolves to the Paperclip host from your runtime
594→- run: pnpm paperclipai allowed-hostname <host>
595→- restart Paperclip
596→- verify with: curl -fsS http://<host>:3100/api/health
597→- regenerate this invite snippet`
598→      : `If none are reachable, ask your user to add a reachable hostname in Paperclip, restart, and retry.
599→Suggested command:
600→- pnpm paperclipai allowed-hostname <host>
601→Then verify with: curl -fsS <base-url>/api/health`;
602→
603→  const resolutionLine = resolutionTestUrl
604→    ? `\nYou MUST test Paperclip-to-gateway reachability, call: ${resolutionTestUrl}?url=<urlencoded-gateway-url> (using the hostname that worked above). Do not assume your 172.x is necessarily reachable from Paperclip. Test it. `
605→    : "";
606→
607→  return `You're invited to join a Paperclip organization.
608→
609→The URLs you should try are:
610→${candidateList}
611→
612→Connectivity guidance:
613→If you are running on a different machine than Paperclip, Paperclip must be reachable at one of the hostnames used above.
614→Verify the hostname works from your runtime with: GET <base-url>/api/health
615→
616→${connectivityBlock}
617→
618→For your "agentName", just use your own agent name (OpenClaw or whatever your name is) and send it directly.
619→You also need to send a gateway URL that Paperclip can access. Check your config and include that URL.${resolutionLine}
620→
621→---
622→
623→This onboarding flow is for OpenClaw Gateway.
624→When you submit the join request, use:
625→- \`adapterType: "openclaw_gateway"\`
626→- \`agentDefaultsPayload.url\` as your \`ws://\` or \`wss://\` gateway URL
627→- \`agentDefaultsPayload.headers["x-openclaw-token"]\` with your gateway token
628→- (legacy accepted) \`agentDefaultsPayload.headers["x-openclaw-auth"]\`
629→- Keep device auth enabled (recommended). If \`devicePrivateKeyPem\` is omitted, Paperclip will generate and persist one during join so pairing approvals remain stable.
630→- Only use \`disableDeviceAuth=true\` for special environments where pairing cannot be completed.
631→
632→Do NOT use \`/v1/responses\` or \`/hooks/*\` in this join flow.
633→
634→Before you do anything, please respond to your user that you understand the instructions and you're going to work on them. Then do the step above in another session called "paperclip-onboarding" and then tell your user when you're done. Update your user in intermediate steps along the way so they know what's going on.
635→
636→Then after you've connected to Paperclip (exchanged keys etc.) you MUST review and follow the onboarding instructions in onboarding.txt they give you.
637→
638→`;
639→}
640→
641→function buildCandidateOnboardingUrls(input: AgentSnippetInput): string[] {
642→  const candidates = (input.connectionCandidates ?? [])
643→    .map((candidate) => candidate.trim())
644→    .filter(Boolean);
645→  const urls = new Set<string>();
646→  let onboardingUrl: URL | null = null;
647→
648→  try {
649→    onboardingUrl = new URL(input.onboardingTextUrl);
650→    urls.add(onboardingUrl.toString());
651→  } catch {
652→    const trimmed = input.onboardingTextUrl.trim();
653→    if (trimmed) {
654→      urls.add(trimmed);
655→    }
656→  }
657→
658→  if (!onboardingUrl) {
659→    for (const candidate of candidates) {
660→      urls.add(candidate);
661→    }
662→    return Array.from(urls);
663→  }
664→
665→  const onboardingPath = `${onboardingUrl.pathname}${onboardingUrl.search}`;
666→  for (const candidate of candidates) {
667→    try {
668→      const base = new URL(candidate);
669→      urls.add(`${base.origin}${onboardingPath}`);
670→    } catch {
671→      urls.add(candidate);
672→    }
673→  }
674→
675→  return Array.from(urls);
676→}
677→
678→function buildResolutionTestUrl(input: AgentSnippetInput): string | null {
679→  const explicit = input.testResolutionUrl?.trim();
680→  if (explicit) return explicit;
681→
682→  try {
683→    const onboardingUrl = new URL(input.onboardingTextUrl);
684→    const testPath = onboardingUrl.pathname.replace(
685→      /\/onboarding\.txt$/,
686→      "/test-resolution"
687→    );
688→    return `${onboardingUrl.origin}${testPath}`;
689→  } catch {
690→    return null;
691→  }
692→}
