 100→/** Resolve the primary type string from a schema node. */
 101→export function resolveType(schema: JsonSchemaNode): string {
 102→  if (schema.enum) return "enum";
 103→  if (schema.const !== undefined) return "const";
 104→  if (schema.format === "secret-ref") return "secret-ref";
 105→  if (Array.isArray(schema.type)) {
 106→    // Use the first non-null type
 107→    return schema.type.find((t) => t !== "null") ?? "string";
 108→  }
 109→  return schema.type ?? "string";
 110→}
 111→
 112→/** Human-readable label from schema title or property key. */
 113→export function labelFromKey(key: string, schema: JsonSchemaNode): string {
 114→  if (schema.title) return schema.title;
 115→  // Convert camelCase / snake_case to Title Case
 116→  return key
 117→    .replace(/([a-z])([A-Z])/g, "$1 $2")
 118→    .replace(/[_-]+/g, " ")
 119→    .replace(/\b\w/g, (c) => c.toUpperCase());
 120→}
 121→
 122→/** Produce a sensible default value for a schema node. */
 123→export function getDefaultForSchema(schema: JsonSchemaNode): unknown {
 124→  if (schema.default !== undefined) return schema.default;
 125→
 126→  const type = resolveType(schema);
 127→  switch (type) {
 128→    case "string":
 129→    case "secret-ref":
 130→      return "";
 131→    case "number":
 132→    case "integer":
 133→      return schema.minimum ?? 0;
 134→    case "boolean":
 135→      return false;
 136→    case "enum":
 137→      return schema.enum?.[0] ?? "";
 138→    case "array":
 139→      return [];
 140→    case "object": {
 141→      if (!schema.properties) return {};
 142→      const obj: Record<string, unknown> = {};
 143→      for (const [key, propSchema] of Object.entries(schema.properties)) {
 144→        obj[key] = getDefaultForSchema(propSchema);
 145→      }
 146→      return obj;
 147→    }
 148→    default:
 149→      return "";
 150→  }
 151→}
 152→
 153→/** Validate a single field value against schema constraints. Returns error string or null. */
 154→export function validateField(
 155→  value: unknown,
 156→  schema: JsonSchemaNode,
 157→  isRequired: boolean,
 158→): string | null {
 159→  const type = resolveType(schema);
 160→
 161→  // Required check
 162→  if (isRequired && (value === undefined || value === null || value === "")) {
 163→    return "This field is required";
 164→  }
 165→
 166→  // Skip further validation if empty and not required
 167→  if (value === undefined || value === null || value === "") return null;
 168→
 169→  if (type === "string" || type === "secret-ref") {
 170→    const str = String(value);
 171→    if (schema.minLength != null && str.length < schema.minLength) {
 172→      return `Must be at least ${schema.minLength} characters`;
 173→    }
 174→    if (schema.maxLength != null && str.length > schema.maxLength) {
 175→      return `Must be at most ${schema.maxLength} characters`;
 176→    }
 177→    if (schema.pattern) {
 178→      // Guard against ReDoS: reject overly complex patterns from plugin JSON Schemas.
 179→      // Limit pattern length and run the regex with a defensive try/catch.
 180→      const MAX_PATTERN_LENGTH = 512;
 181→      if (schema.pattern.length <= MAX_PATTERN_LENGTH) {
 182→        try {
 183→          const re = new RegExp(schema.pattern);
 184→          if (!re.test(str)) {
 185→            return `Must match pattern: ${schema.pattern}`;
 186→          }
 187→        } catch {
 188→          // Invalid regex in schema — skip
 189→        }
 190→      }
 191→    }
 192→  }
 193→
 194→  if (type === "number" || type === "integer") {
 195→    const num = Number(value);
 196→    if (isNaN(num)) return "Must be a valid number";
 197→    if (schema.minimum != null && num < schema.minimum) {
 198→      return `Must be at least ${schema.minimum}`;
 199→    }
 200→    if (schema.maximum != null && num > schema.maximum) {
 201→      return `Must be at most ${schema.maximum}`;
 202→    }
 203→    if (schema.exclusiveMinimum != null && num <= schema.exclusiveMinimum) {
 204→      return `Must be greater than ${schema.exclusiveMinimum}`;
 205→    }
 206→    if (schema.exclusiveMaximum != null && num >= schema.exclusiveMaximum) {
 207→      return `Must be less than ${schema.exclusiveMaximum}`;
 208→    }
 209→    if (type === "integer" && !Number.isInteger(num)) {
 210→      return "Must be a whole number";
 211→    }
 212→    if (schema.multipleOf != null && num % schema.multipleOf !== 0) {
 213→      return `Must be a multiple of ${schema.multipleOf}`;
 214→    }
 215→  }
 216→
 217→  if (type === "array") {
 218→    const arr = value as unknown[];
 219→    if (schema.minItems != null && arr.length < schema.minItems) {
 220→      return `Must have at least ${schema.minItems} items`;
 221→    }
 222→    if (schema.maxItems != null && arr.length > schema.maxItems) {
 223→      return `Must have at most ${schema.maxItems} items`;
 224→    }
 225→  }
 226→
 227→  return null;
 228→}
 229→
 230→/** Public API for validation */
 231→export function validateJsonSchemaForm(
 232→  schema: JsonSchemaNode,
 233→  values: Record<string, unknown>,
 234→  path: string[] = [],
 235→): Record<string, string> {
 236→  const errors: Record<string, string> = {};
 237→  const properties = schema.properties ?? {};
 238→  const requiredFields = new Set(schema.required ?? []);
 239→
 240→  for (const [key, propSchema] of Object.entries(properties)) {
 241→    const fieldPath = [...path, key];
 242→    const errorKey = `/${fieldPath.join("/")}`;
 243→    const value = values[key];
 244→    const isRequired = requiredFields.has(key);
 245→    const type = resolveType(propSchema);
 246→
 247→    // Per-field validation
 248→    const fieldErr = validateField(value, propSchema, isRequired);
 249→    if (fieldErr) {
 250→      errors[errorKey] = fieldErr;
 251→    }
 252→
 253→    // Recurse into objects
 254→    if (type === "object" && propSchema.properties && typeof value === "object" && value !== null) {
 255→      Object.assign(
 256→        errors,
 257→        validateJsonSchemaForm(propSchema, value as Record<string, unknown>, fieldPath),
 258→      );
 259→    }
 260→
 261→    // Recurse into arrays
 262→    if (type === "array" && propSchema.items && Array.isArray(value)) {
 263→      const itemSchema = propSchema.items as JsonSchemaNode;
 264→      const isObjectItem = resolveType(itemSchema) === "object";
 265→
 266→      value.forEach((item, index) => {
 267→        const itemPath = [...fieldPath, String(index)];
 268→        const itemErrorKey = `/${itemPath.join("/")}`;
 269→
 270→        if (isObjectItem) {
 271→          Object.assign(
 272→            errors,
 273→            validateJsonSchemaForm(
 274→              itemSchema,
 275→              item as Record<string, unknown>,
 276→              itemPath,
 277→            ),
 278→          );
 279→        } else {
 280→          const itemErr = validateField(item, itemSchema, false);
 281→          if (itemErr) {
 282→            errors[itemErrorKey] = itemErr;
 283→          }
 284→        }
 285→      });
 286→    }
 287→  }
 288→
 289→  return errors;
 290→}
 291→
 292→/** Public API for default values */
 293→export function getDefaultValues(schema: JsonSchemaNode): Record<string, unknown> {
 294→  const result: Record<string, unknown> = {};
 295→  const properties = schema.properties ?? {};
 296→
 297→  for (const [key, propSchema] of Object.entries(properties)) {
 298→    const def = getDefaultForSchema(propSchema);
 299→    if (def !== undefined) {
 300→      result[key] = def;
 301→    }
 302→  }
 303→
 304→  return result;
 305→}
