 182→      if (schema.pattern.length <= MAX_PATTERN_LENGTH) {
 183→        try {
 184→          const re = new RegExp(schema.pattern);
 185→          if (!re.test(str)) {
 186→            return `Must match pattern: ${schema.pattern}`;
 187→          }
 188→        } catch {
 189→          // Invalid regex in schema — skip
 190→        }
 191→      }
 192→    }
 193→  }
 194→
 195→  if (type === "number" || type === "integer") {
 196→    const num = Number(value);
 197→    if (isNaN(num)) return "Must be a valid number";
 198→    if (schema.minimum != null && num < schema.minimum) {
 199→      return `Must be at least ${schema.minimum}`;
 200→    }
 201→    if (schema.maximum != null && num > schema.maximum) {
 202→      return `Must be at most ${schema.maximum}`;
 203→    }
 204→    if (schema.exclusiveMinimum != null && num <= schema.exclusiveMinimum) {
 205→      return `Must be greater than ${schema.exclusiveMinimum}`;
 206→    }
 207→    if (schema.exclusiveMaximum != null && num >= schema.exclusiveMaximum) {
 208→      return `Must be less than ${schema.exclusiveMaximum}`;
 209→    }
 210→    if (type === "integer" && !Number.isInteger(num)) {
 211→      return "Must be a whole number";
 212→    }
 213→    if (schema.multipleOf != null && num % schema.multipleOf !== 0) {
 214→      return `Must be a multiple of ${schema.multipleOf}`;
 215→    }
 216→  }
 217→
 218→  if (type === "array") {
 219→    const arr = value as unknown[];
 220→    if (schema.minItems != null && arr.length < schema.minItems) {
 221→      return `Must have at least ${schema.minItems} items`;
 222→    }
 223→    if (schema.maxItems != null && arr.length > schema.maxItems) {
 224→      return `Must have at most ${schema.maxItems} items`;
 225→    }
 226→  }
 227→
 228→  return null;
 229→}
 230→
 231→/** Public API for validation */
 232→export function validateJsonSchemaForm(
 233→  schema: JsonSchemaNode,
 234→  values: Record<string, unknown>,
 235→  path: string[] = [],
 236→): Record<string, string> {
 237→  const errors: Record<string, string> = {};
 238→  const properties = schema.properties ?? {};
 239→  const requiredFields = new Set(schema.required ?? []);
 240→
 241→  for (const [key, propSchema] of Object.entries(properties)) {
 242→    const fieldPath = [...path, key];
 243→    const errorKey = `/${fieldPath.join("/")}`;
 244→    const value = values[key];
 245→    const isRequired = requiredFields.has(key);
 246→    const type = resolveType(propSchema);
 247→
 248→    // Per-field validation
 249→    const fieldErr = validateField(value, propSchema, isRequired);
 250→    if (fieldErr) {
 251→      errors[errorKey] = fieldErr;
 252→    }
 253→
 254→    // Recurse into objects
 255→    if (type === "object" && propSchema.properties && typeof value === "object" && value !== null) {
 256→      Object.assign(
 257→        errors,
 258→        validateJsonSchemaForm(propSchema, value as Record<string, unknown>, fieldPath),
 259→      );
 260→    }
 261→
 262→    // Recurse into arrays
 263→    if (type === "array" && propSchema.items && Array.isArray(value)) {
 264→      const itemSchema = propSchema.items as JsonSchemaNode;
 265→      const isObjectItem = resolveType(itemSchema) === "object";
 266→
 267→      value.forEach((item, index) => {
 268→        const itemPath = [...fieldPath, String(index)];
 269→        const itemErrorKey = `/${itemPath.join("/")}`;
 270→
 271→        if (isObjectItem) {
 272→          Object.assign(
 273→            errors,
 274→            validateJsonSchemaForm(
 275→              itemSchema,
 276→              item as Record<string, unknown>,
 277→              itemPath,
 278→            ),
 279→          );
 280→        } else {
 281→          const itemErr = validateField(item, itemSchema, false);
 282→          if (itemErr) {
 283→            errors[itemErrorKey] = itemErr;
 284→          }
 285→        }
 286→      });
 287→    }
 288→  }
 289→
 290→  return errors;
 291→}
 292→
 293→/** Public API for default values */
 294→export function getDefaultValues(schema: JsonSchemaNode): Record<string, unknown> {
 295→  const result: Record<string, unknown> = {};
 296→  const properties = schema.properties ?? {};
 297→
 298→  for (const [key, propSchema] of Object.entries(properties)) {
 299→    const def = getDefaultForSchema(propSchema);
 300→    if (def !== undefined) {
 301→      result[key] = def;
 302→    }
 303→  }
 304→
 305→  return result;
 306→}
