 647→/**
 648→ * Specialized field for selecting a company by ID.
 649→ * Rendered automatically when a plugin schema field key is "companyId".
 650→ */
 651→const CompanySelectField = React.memo(({
 652→  value,
 653→  onChange,
 654→  disabled,
 655→  label,
 656→  isRequired,
 657→  description,
 658→  error,
 659→}: {
 660→  value: unknown;
 661→  onChange: (val: unknown) => void;
 662→  disabled: boolean;
 663→  label: string;
 664→  isRequired?: boolean;
 665→  description?: string;
 666→  error?: string;
 667→}) => {
 668→  const { companies, selectedCompanyId } = useCompany();
 669→  const activeCompanies = useMemo(
 670→    () => companies.filter((c) => c.status !== "archived"),
 671→    [companies],
 672→  );
 673→
 674→  // Value priority chain:
 675→  // 1. Saved value matching a valid (non-archived) company → keep it
 676→  // 2. Empty/null or references archived/deleted company → default to current company
 677→  // 3. Single company → auto-select
 678→  const currentValue = useMemo(() => {
 679→    const strVal = value ? String(value) : "";
 680→    if (strVal && activeCompanies.some((c) => c.id === strVal)) {
 681→      return strVal;
 682→    }
 683→    if (selectedCompanyId && activeCompanies.some((c) => c.id === selectedCompanyId)) {
 684→      return selectedCompanyId;
 685→    }
 686→    if (activeCompanies.length === 1) {
 687→      return activeCompanies[0]!.id;
 688→    }
 689→    return "";
 690→  }, [value, activeCompanies, selectedCompanyId]);
 691→
 692→  // Auto-set value when it differs from what's stored
 693→  useEffect(() => {
 694→    if (currentValue && currentValue !== String(value ?? "")) {
 695→      onChange(currentValue);
 696→    }
 697→  }, [currentValue]); // eslint-disable-line react-hooks/exhaustive-deps
 698→
 699→  if (activeCompanies.length === 0) {
 700→    return (
 701→      <FieldWrapper
 702→        label={label}
 703→        description={description}
 704→        required={isRequired}
 705→        error={error}
 706→        disabled
 707→      >
 708→        <Select disabled>
 709→          <SelectTrigger className="w-full">
 710→            <SelectValue placeholder="No companies available" />
 711→          </SelectTrigger>
 712→        </Select>
 713→      </FieldWrapper>
 714→    );
 715→  }
 716→
 717→  return (
 718→    <FieldWrapper
 719→      label={label}
 720→      description={description}
 721→      required={isRequired}
 722→      error={error}
 723→      disabled={disabled}
 724→    >
 725→      <Select
 726→        value={currentValue}
 727→        onValueChange={onChange}
 728→        disabled={disabled}
 729→      >
 730→        <SelectTrigger className="w-full">
 731→          <SelectValue placeholder="Select a company" />
 732→        </SelectTrigger>
 733→        <SelectContent>
 734→          {activeCompanies.map((company) => (
 735→            <SelectItem key={company.id} value={company.id}>
 736→              {company.name}
 737→              {company.issuePrefix ? ` (${company.issuePrefix})` : ""}
 738→            </SelectItem>
 739→          ))}
 740→        </SelectContent>
 741→      </Select>
 742→    </FieldWrapper>
 743→  );
 744→});
