  41→ * level to match the `JsonSchema` type in shared, but narrow internally.
  42→ */
  43→export interface JsonSchemaNode {
  44→  type?: string | string[];
  45→  title?: string;
  46→  description?: string;
  47→  default?: unknown;
  48→  enum?: unknown[];
  49→  const?: unknown;
  50→  format?: string;
  51→
  52→  // String constraints
  53→  minLength?: number;
  54→  maxLength?: number;
  55→  pattern?: string;
  56→
  57→  // Number constraints
  58→  minimum?: number;
  59→  maximum?: number;
  60→  exclusiveMinimum?: number;
  61→  exclusiveMaximum?: number;
  62→  multipleOf?: number;
  63→
  64→  // Object
  65→  properties?: Record<string, JsonSchemaNode>;
  66→  required?: string[];
  67→  additionalProperties?: boolean | JsonSchemaNode;
  68→
  69→  // Array
  70→  items?: JsonSchemaNode;
  71→  minItems?: number;
  72→  maxItems?: number;
  73→
  74→  // Metadata
  75→  readOnly?: boolean;
  76→  writeOnly?: boolean;
  77→
  78→  // Allow extra keys
  79→  [key: string]: unknown;
  80→}
  81→
  82→export interface JsonSchemaFormProps {
  83→  /** The JSON Schema to render. */
  84→  schema: JsonSchemaNode;
  85→  /** Current form values. */
  86→  values: Record<string, unknown>;
  87→  /** Called whenever any field value changes. */
  88→  onChange: (values: Record<string, unknown>) => void;
  89→  /** Validation errors keyed by JSON pointer path (e.g. "/apiKey"). */
  90→  errors?: Record<string, string>;
  91→  /** If true, all fields are disabled. */
  92→  disabled?: boolean;
  93→  /** Additional CSS class for the root container. */
  94→  className?: string;
  95→}
  96→
  97→// ---------------------------------------------------------------------------
  98→// Helpers
  99→// ---------------------------------------------------------------------------
 100→
 101→/** Resolve the primary type string from a schema node. */
 102→export function resolveType(schema: JsonSchemaNode): string {
 103→  if (schema.enum) return "enum";
 104→  if (schema.const !== undefined) return "const";
 105→  if (schema.format === "secret-ref") return "secret-ref";
 106→  if (Array.isArray(schema.type)) {
 107→    // Use the first non-null type
 108→    return schema.type.find((t) => t !== "null") ?? "string";
 109→  }
 110→  return schema.type ?? "string";
 111→}
 112→
 113→/** Human-readable label from schema title or property key. */
 114→export function labelFromKey(key: string, schema: JsonSchemaNode): string {
 115→  if (schema.title) return schema.title;
 116→  // Convert camelCase / snake_case to Title Case
 117→  return key
 118→    .replace(/([a-z])([A-Z])/g, "$1 $2")
 119→    .replace(/[_-]+/g, " ")
 120→    .replace(/\b\w/g, (c) => c.toUpperCase());
 121→}
 122→
 123→/** Produce a sensible default value for a schema node. */
 124→export function getDefaultForSchema(schema: JsonSchemaNode): unknown {
 125→  if (schema.default !== undefined) return schema.default;
 126→
 127→  const type = resolveType(schema);
 128→  switch (type) {
 129→    case "string":
 130→    case "secret-ref":
 131→      return "";
 132→    case "number":
 133→    case "integer":
 134→      return schema.minimum ?? 0;
 135→    case "boolean":
 136→      return false;
 137→    case "enum":
 138→      return schema.enum?.[0] ?? "";
 139→    case "array":
 140→      return [];
 141→    case "object": {
 142→      if (!schema.properties) return {};
 143→      const obj: Record<string, unknown> = {};
 144→      for (const [key, propSchema] of Object.entries(schema.properties)) {
 145→        obj[key] = getDefaultForSchema(propSchema);
 146→      }
 147→      return obj;
 148→    }
 149→    default:
 150→      return "";
 151→  }
 152→}
 153→
 154→/** Validate a single field value against schema constraints. Returns error string or null. */
 155→export function validateField(
 156→  value: unknown,
 157→  schema: JsonSchemaNode,
 158→  isRequired: boolean,
 159→): string | null {
 160→  const type = resolveType(schema);
 161→
 162→  // Required check
 163→  if (isRequired && (value === undefined || value === null || value === "")) {
 164→    return "This field is required";
 165→  }
 166→
 167→  // Skip further validation if empty and not required
 168→  if (value === undefined || value === null || value === "") return null;
 169→
 170→  if (type === "string" || type === "secret-ref") {
 171→    const str = String(value);
 172→    if (schema.minLength != null && str.length < schema.minLength) {
 173→      return `Must be at least ${schema.minLength} characters`;
 174→    }
 175→    if (schema.maxLength != null && str.length > schema.maxLength) {
 176→      return `Must be at most ${schema.maxLength} characters`;
 177→    }
 178→    if (schema.pattern) {
 179→      // Guard against ReDoS: reject overly complex patterns from plugin JSON Schemas.
 180→      // Limit pattern length and run the regex with a defensive try/catch.
 181→      const MAX_PATTERN_LENGTH = 512;
 182→      if (schema.pattern.length <= MAX_PATTERN_LENGTH) {
 183→        try {
 184→          const re = new RegExp(schema.pattern);
 185→          if (!re.test(str)) {
 186→            return `Must match pattern: ${schema.pattern}`;
 187→          }
 188→        } catch {
 189→          // Invalid regex in schema — skip
 190→        }
 191→      }
 192→    }
 193→  }
 194→
 195→  if (type === "number" || type === "integer") {
 196→    const num = Number(value);
 197→    if (isNaN(num)) return "Must be a valid number";
 198→    if (schema.minimum != null && num < schema.minimum) {
 199→      return `Must be at least ${schema.minimum}`;
 200→    }
 201→    if (schema.maximum != null && num > schema.maximum) {
 202→      return `Must be at most ${schema.maximum}`;
 203→    }
 204→    if (schema.exclusiveMinimum != null && num <= schema.exclusiveMinimum) {
 205→      return `Must be greater than ${schema.exclusiveMinimum}`;
 206→    }
 207→    if (schema.exclusiveMaximum != null && num >= schema.exclusiveMaximum) {
 208→      return `Must be less than ${schema.exclusiveMaximum}`;
 209→    }
 210→    if (type === "integer" && !Number.isInteger(num)) {
 211→      return "Must be a whole number";
 212→    }
 213→    if (schema.multipleOf != null && num % schema.multipleOf !== 0) {
 214→      return `Must be a multiple of ${schema.multipleOf}`;
 215→    }
 216→  }
 217→
 218→  if (type === "array") {
 219→    const arr = value as unknown[];
 220→    if (schema.minItems != null && arr.length < schema.minItems) {
 221→      return `Must have at least ${schema.minItems} items`;
 222→    }
 223→    if (schema.maxItems != null && arr.length > schema.maxItems) {
 224→      return `Must have at most ${schema.maxItems} items`;
 225→    }
 226→  }
 227→
 228→  return null;
 229→}
 230→
 231→/** Public API for validation */
 232→export function validateJsonSchemaForm(
 233→  schema: JsonSchemaNode,
 234→  values: Record<string, unknown>,
 235→  path: string[] = [],
 236→): Record<string, string> {
 237→  const errors: Record<string, string> = {};
 238→  const properties = schema.properties ?? {};
 239→  const requiredFields = new Set(schema.required ?? []);
 240→
 241→  for (const [key, propSchema] of Object.entries(properties)) {
 242→    const fieldPath = [...path, key];
 243→    const errorKey = `/${fieldPath.join("/")}`;
 244→    const value = values[key];
 245→    const isRequired = requiredFields.has(key);
 246→    const type = resolveType(propSchema);
 247→
 248→    // Per-field validation
 249→    const fieldErr = validateField(value, propSchema, isRequired);
 250→    if (fieldErr) {
 251→      errors[errorKey] = fieldErr;
 252→    }
 253→
 254→    // Recurse into objects
 255→    if (type === "object" && propSchema.properties && typeof value === "object" && value !== null) {
 256→      Object.assign(
 257→        errors,
 258→        validateJsonSchemaForm(propSchema, value as Record<string, unknown>, fieldPath),
 259→      );
 260→    }
 261→
 262→    // Recurse into arrays
 263→    if (type === "array" && propSchema.items && Array.isArray(value)) {
 264→      const itemSchema = propSchema.items as JsonSchemaNode;
 265→      const isObjectItem = resolveType(itemSchema) === "object";
 266→
 267→      value.forEach((item, index) => {
 268→        const itemPath = [...fieldPath, String(index)];
 269→        const itemErrorKey = `/${itemPath.join("/")}`;
 270→
 271→        if (isObjectItem) {
 272→          Object.assign(
 273→            errors,
 274→            validateJsonSchemaForm(
 275→              itemSchema,
 276→              item as Record<string, unknown>,
 277→              itemPath,
 278→            ),
 279→          );
 280→        } else {
 281→          const itemErr = validateField(item, itemSchema, false);
 282→          if (itemErr) {
 283→            errors[itemErrorKey] = itemErr;
 284→          }
 285→        }
 286→      });
 287→    }
 288→  }
 289→
 290→  return errors;
 291→}
 292→
 293→/** Public API for default values */
 294→export function getDefaultValues(schema: JsonSchemaNode): Record<string, unknown> {
 295→  const result: Record<string, unknown> = {};
 296→  const properties = schema.properties ?? {};
 297→
 298→  for (const [key, propSchema] of Object.entries(properties)) {
 299→    const def = getDefaultForSchema(propSchema);
 300→    if (def !== undefined) {
 301→      result[key] = def;
 302→    }
 303→  }
 304→
 305→  return result;
 306→}
