 912→
 913→      {!isCollapsed && (
 914→        <div className="pt-2">
 915→          <JsonSchemaForm
 916→            schema={propSchema}
 917→            values={(value as Record<string, unknown>) ?? {}}
 918→            onChange={handleObjectChange}
