 934→/**
 935→ * Orchestrator component that selects and renders the appropriate field type based on the schema node.
 936→ */
 937→const FormField = React.memo(({
 938→  fieldKey,
 939→  propSchema,
 940→  value,
 941→  onChange,
 942→  error,
 943→  disabled,
 944→  label,
 945→  isRequired,
 946→  errors,
 947→  path,
 948→}: FormFieldProps) => {
 949→  const type = resolveType(propSchema);
 950→  const isReadOnly = disabled || propSchema.readOnly === true;
 951→
 952→  // Key-based override: render company selector for companyId fields
 953→  if (fieldKey === "companyId" && (type === "string" || type === "enum")) {
 954→    return (
 955→      <CompanySelectField
 956→        value={value}
 957→        onChange={onChange}
 958→        disabled={isReadOnly}
 959→        label={label}
 960→        isRequired={isRequired}
 961→        description={propSchema.description}
 962→        error={error}
 963→      />
 964→    );
 965→  }
 966→
 967→  switch (type) {
 968→    case "boolean":
 969→      return (
 970→        <BooleanField
 971→          id={path}
 972→          value={value}
 973→          onChange={onChange}
 974→          disabled={isReadOnly}
 975→          label={label}
 976→          isRequired={isRequired}
 977→          description={propSchema.description}
 978→          error={error}
 979→        />
 980→      );
 981→
 982→    case "enum":
 983→      return (
 984→        <EnumField
 985→          value={value}
 986→          onChange={onChange}
 987→          disabled={isReadOnly}
 988→          label={label}
 989→          isRequired={isRequired}
 990→          description={propSchema.description}
 991→          error={error}
 992→          options={propSchema.enum ?? []}
 993→        />
 994→      );
 995→
 996→    case "secret-ref":
 997→      return (
 998→        <SecretField
 999→          value={value}
1000→          onChange={onChange}
1001→          disabled={isReadOnly}
1002→          label={label}
1003→          isRequired={isRequired}
1004→          description={propSchema.description}
1005→          error={error}
1006→          defaultValue={propSchema.default}
1007→        />
1008→      );
1009→
1010→    case "number":
1011→    case "integer":
1012→      return (
1013→        <NumberField
1014→          value={value}
1015→          onChange={onChange}
1016→          disabled={isReadOnly}
1017→          label={label}
1018→          isRequired={isRequired}
1019→          description={propSchema.description}
1020→          error={error}
1021→          defaultValue={propSchema.default}
1022→          type={type as "number" | "integer"}
1023→        />
1024→      );
1025→
1026→    case "array":
1027→      return (
1028→        <ArrayField
1029→          propSchema={propSchema}
1030→          value={value}
1031→          onChange={onChange}
1032→          error={error}
1033→          disabled={isReadOnly}
1034→          label={label}
1035→          errors={errors}
1036→          path={path}
1037→        />
1038→      );
1039→
1040→    case "object":
1041→      return (
1042→        <ObjectField
1043→          propSchema={propSchema}
1044→          value={value}
1045→          onChange={onChange}
1046→          disabled={isReadOnly}
1047→          label={label}
1048→          errors={errors}
1049→          path={path}
1050→        />
1051→      );
1052→
1053→    default: // string
1054→      return (
1055→        <StringField
1056→          value={value}
1057→          onChange={onChange}
1058→          disabled={isReadOnly}
1059→          label={label}
1060→          isRequired={isRequired}
1061→          description={propSchema.description}
1062→          error={error}
1063→          defaultValue={propSchema.default}
1064→          format={propSchema.format}
1065→          maxLength={propSchema.maxLength}
1066→        />
1067→      );
1068→  }
1069→});
1070→
1071→FormField.displayName = "FormField";
1072→
1073→// ---------------------------------------------------------------------------
1074→// Main Component
1075→// ---------------------------------------------------------------------------
1076→
1077→/**
1078→ * Main JsonSchemaForm component.
1079→ * Renders a form based on a subset of JSON Schema specification.
1080→ * Supports primitive types, enums, secrets, objects, and arrays with recursion.
1081→ */
1082→export function JsonSchemaForm({
1083→  schema,
1084→  values,
1085→  onChange,
1086→  errors = {},
1087→  disabled,
1088→  className,
1089→}: JsonSchemaFormProps) {
1090→  const type = resolveType(schema);
1091→
1092→  const handleRootScalarChange = useCallback((newVal: unknown) => {
1093→    // If root is a scalar, values IS the value
1094→    onChange(newVal as Record<string, unknown>);
1095→  }, [onChange]);
1096→
1097→  // If it's a scalar at root, render a single FormField
1098→  if (type !== "object") {
1099→    return (
1100→      <div className={className}>
1101→        <FormField
1102→          propSchema={schema}
1103→          value={values}
1104→          label=""
1105→          path=""
1106→          onChange={handleRootScalarChange}
1107→          disabled={disabled}
1108→          errors={errors}
1109→        />
1110→      </div>
1111→    );
1112→  }
1113→
1114→  // Memoize to avoid re-renders when parent provides new object references
1115→  const properties = useMemo(() => schema.properties ?? {}, [schema.properties]);
1116→  const requiredFields = useMemo(
1117→    () => new Set(schema.required ?? []),
1118→    [schema.required],
1119→  );
1120→
1121→  const handleFieldChange = useCallback(
1122→    (key: string, value: unknown) => {
1123→      onChange({ ...values, [key]: value });
1124→    },
1125→    [onChange, values],
1126→  );
1127→
1128→  if (Object.keys(properties).length === 0) {
1129→    return (
1130→      <div
1131→        className={cn(
1132→          "py-4 text-center text-sm text-muted-foreground",
1133→          className,
1134→        )}
1135→      >
1136→        No configuration options available.
1137→      </div>
1138→    );
1139→  }
1140→
1141→  return (
1142→    <div className={cn("space-y-6", className)}>
1143→      {Object.entries(properties).map(([key, propSchema]) => {
1144→        const value = values[key];
1145→        const isRequired = requiredFields.has(key);
1146→        const error = errors[`/${key}`];
1147→        const label = labelFromKey(key, propSchema);
1148→        const path = `/${key}`;
1149→
1150→        return (
1151→          <FormField
1152→            key={key}
1153→            fieldKey={key}
1154→            propSchema={propSchema}
1155→            value={value}
1156→            onChange={(val) => handleFieldChange(key, val)}
1157→            error={error}
1158→            disabled={disabled}
1159→            label={label}
1160→            isRequired={isRequired}
1161→            errors={errors}
1162→            path={path}
1163→          />
1164→        );
1165→      })}
1166→    </div>
1167→  );
1168→}
