    renderWithProviders(
      <JsonSchemaForm
        schema={schema}
        values={{ companyId: "" }}
        onChange={vi.fn()}
      />,
    );

    // Should render a select trigger (dropdown), not a text input
    expect(screen.getByRole("combobox")).toBeInTheDocument();
    expect(screen.queryByRole("textbox")).not.toBeInTheDocument();
